def _uploaded_file(args: dict, key: str, limit: int = 12 * 1024 * 1024) -> tuple[bytes,str,str]:
    item=args.get(key)
    if not isinstance(item,dict): raise ValueError("Choose a file before running this tool.")
    raw=str(item.get("data", ""))
    if not raw: raise ValueError("The selected file is empty.")
    try: blob=base64.b64decode(raw,validate=True)
    except Exception as exc: raise ValueError("The uploaded file data is invalid.") from exc
    if len(blob)>limit: raise ValueError("The file is too large for this utility (12 MB maximum).")
    return blob,str(item.get("mime_type","application/octet-stream")),str(item.get("name","upload.bin"))


def _image_result(blob: bytes, mime: str, filename: str) -> dict:
    return {"filename":filename,"mime_type":mime,"bytes":len(blob),"image_base64":base64.b64encode(blob).decode("ascii"),"image_mime":mime}


def _make_qr(payload: str, name: str = "jarvis-qr.png") -> dict:
    if not payload.strip(): raise ValueError("Enter some text or a URL first.")
    if len(payload)>2500: raise ValueError("QR content is limited to 2,500 characters.")
    try:
        import qrcode
        from PIL import Image
    except ImportError as exc: raise ValueError("QR generation needs qrcode and Pillow. Install the updated requirements.txt.") from exc
    qr=qrcode.QRCode(version=None,error_correction=qrcode.constants.ERROR_CORRECT_M,box_size=8,border=4)
    qr.add_data(payload); qr.make(fit=True)
    image=qr.make_image(fill_color="#07111d",back_color="white").convert("RGB")
    buf=io.BytesIO(); image.save(buf,format="PNG")
    return _image_result(buf.getvalue(),"image/png",name)


def _hex_rgb(value: str) -> tuple[int,int,int]:
    s=str(value).strip().lstrip("#")
    if len(s)==3: s="".join(ch*2 for ch in s)
    if not re.fullmatch(r"[0-9a-fA-F]{6}",s): raise ValueError("Enter a 3- or 6-digit HEX colour.")
    return tuple(int(s[i:i+2],16) for i in (0,2,4))


def _rgb_hex(rgb: tuple[int,int,int]) -> str:
    return "#"+"".join(f"{max(0,min(255,int(c))):02X}" for c in rgb)


