def _validate_svg_source(source: str) -> bytes:
    """Validate SVG as a small, self-contained vector document; never execute embedded content."""
    source = str(source or "").strip()
    if not source:
        raise ValueError("Paste SVG source code first.")
    if len(source.encode("utf-8")) > 120_000:
        raise ValueError("SVG source is limited to 120 KB.")
    if re.search(r"<!DOCTYPE|<!ENTITY|<\s*(script|foreignObject|iframe|object|embed)\b", source, re.I):
        raise ValueError("SVG contains a blocked document type or active element.")
    try:
        parser = ET.XMLParser()
        root = ET.fromstring(source.encode("utf-8"), parser=parser)
    except Exception as exc:
        raise ValueError("SVG is not valid XML: " + str(exc)[:180]) from exc

    def local_name(tag: str) -> str:
        return tag.split("}", 1)[-1] if "}" in tag else tag

    if local_name(root.tag) != "svg":
        raise ValueError("The document root must be an <svg> element.")
    for node in root.iter():
        tag = local_name(node.tag)
        if tag not in _SVG_ALLOWED_TAGS:
            raise ValueError(f"SVG element <{tag}> is not allowed.")
        for raw_key, raw_value in list(node.attrib.items()):
            key = local_name(raw_key)
            value = str(raw_value).strip()
            if key not in _SVG_ALLOWED_ATTRS:
                raise ValueError(f"SVG attribute '{key}' is not allowed.")
            if key == "xmlns" and value != "http://www.w3.org/2000/svg":
                raise ValueError("Only the standard SVG namespace is allowed.")
            if key == "href":
                if not value.startswith("#"):
                    raise ValueError("External SVG links are blocked.")
            if re.search(r"url\s*\(", value, re.I) and not re.fullmatch(r"url\(\s*#[A-Za-z_][\w.-]*\s*\)", value):
                raise ValueError("Only local SVG references such as url(#gradient) are allowed.")
            if key.startswith("on"):
                raise ValueError("SVG event handlers are blocked.")
            if key == "d" and not re.fullmatch(r"[0-9eE+.,\-\sMmLlHhVvCcSsQqTtAaZz]*", value):
                raise ValueError("SVG path data contains unsupported characters.")
            if key == "transform" and not re.fullmatch(r"[A-Za-z0-9(),.+\-\s]*", value):
                raise ValueError("SVG transform contains unsupported characters.")
    # Serialize the parsed tree so malformed markup cannot be passed through verbatim.
    clean = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return clean


def _svg_builder_result(source: str, filename: str = "jarvis-vector.svg") -> dict:
    blob = _validate_svg_source(source)
    safe_name = re.sub(r"[^A-Za-z0-9._-]", "_", str(filename or "jarvis-vector.svg"))[:90]
    if not safe_name.lower().endswith(".svg"):
        safe_name += ".svg"
    return {
        "ok": True, "filename": safe_name, "image_mime": "image/svg+xml",
        "image_base64": base64.b64encode(blob).decode("ascii"),
        "bytes": len(blob), "format": "SVG", "validated": True,
        "sha256": hashlib.sha256(blob).hexdigest()
    }


def _offline_svg_image_generation(prompt: str, cfg: dict | None = None) -> dict:
    """Offline vector-poster fallback. This is procedural artwork, not a neural diffusion model."""
    prompt = str(prompt or "").strip()
    if not prompt:
        raise ValueError("Enter an image description.")
    if len(prompt) > 5000:
        raise ValueError("Image prompt is limited to 5,000 characters.")
    cfg = cfg or {}
    aspect = str(cfg.get("image_aspect_ratio", "1:1"))
    ratios = {"1:1":(1024,1024), "16:9":(1280,720), "9:16":(720,1280), "4:3":(1024,768), "3:4":(768,1024), "3:2":(1200,800), "2:3":(800,1200)}
    width, height = ratios.get(aspect, (1024,1024))
    # Pick a palette from prompt keywords to make the offline result responsive to intent.
    lower = prompt.lower()
    palettes = [
        (("space", "galaxy", "planet", "star", "cosmic"), ("#07152f", "#32246f", "#59d9ff")),
        (("forest", "nature", "tree", "garden", "leaf"), ("#092e26", "#1d7656", "#c1e6a4")),
        (("sunset", "sunrise", "warm", "desert"), ("#451c3a", "#e46c4f", "#ffd17a")),
        (("ocean", "sea", "water", "wave"), ("#06283f", "#087e9c", "#8ce8e1")),
        (("robot", "ai", "technology", "futuristic", "cyber"), ("#071522", "#174b67", "#63e7ff")),
    ]
    bg1,bg2,accent = ("#101b35", "#273b64", "#83e1ff")
    for words, palette in palettes:
        if any(word in lower for word in words):
            bg1,bg2,accent = palette
            break
    safe_prompt = html.escape(prompt[:180], quote=False)
    title = html.escape(" ".join(prompt.split()[:6])[:48], quote=False) or "JARVIS ART"
    subtitle = html.escape(prompt[:110], quote=False)
    # Draw a deterministic, local poster with layered circles and decorative lines.
    circles = []
    cx, cy = width * 0.77, height * 0.34
    for i, (rad, op) in enumerate(((height*.23,.10),(height*.17,.13),(height*.105,.20))):
        circles.append(f'<circle cx="{cx:.1f}" cy="{cy:.1f}" r="{rad:.1f}" fill="none" stroke="{accent}" stroke-width="2" opacity="{op}"/>')
    stars = []
    for i in range(22):
        x = (i * 137 + 53) % width
        y = (i * 89 + 37) % height
        r = 1.4 + (i % 4) * .65
        stars.append(f'<circle cx="{x}" cy="{y}" r="{r:.1f}" fill="#ffffff" opacity="{0.18 + (i%5)*0.1:.2f}"/>')
    svg = f"""<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">
<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="{bg1}"/><stop offset="100%" stop-color="{bg2}"/></linearGradient><linearGradient id="accent" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stop-color="{accent}"/><stop offset="100%" stop-color="#b49cff"/></linearGradient></defs>
<rect width="100%" height="100%" fill="url(#bg)"/>{''.join(stars)}{''.join(circles)}
<path d="M {width*.08:.1f} {height*.67:.1f} H {width*.92:.1f}" stroke="{accent}" stroke-width="2" opacity=".45"/>
<text x="{width*.08:.1f}" y="{height*.20:.1f}" fill="{accent}" font-family="Arial,sans-serif" font-size="{max(14,int(height*.025))}" letter-spacing="4">J.A.R.V.I.S. · LOCAL ART</text>
<text x="{width*.08:.1f}" y="{height*.76:.1f}" fill="url(#accent)" font-family="Arial,sans-serif" font-size="{max(25,int(height*.075))}" font-weight="700">{title}</text>
<text x="{width*.08:.1f}" y="{height*.82:.1f}" fill="#ffffff" opacity=".78" font-family="Arial,sans-serif" font-size="{max(12,int(height*.024))}">{subtitle}</text>
<text x="{width*.08:.1f}" y="{height*.93:.1f}" fill="#ffffff" opacity=".45" font-family="Arial,sans-serif" font-size="{max(10,int(height*.016))}">OFFLINE VECTOR GENERATION · NO API KEY</text></svg>"""
    return _svg_builder_result(svg, "jarvis-offline-art.svg") | {
        "provider": "offline-svg", "text": "Created locally as procedural vector artwork. This offline fallback is not a neural text-to-image model."
    }


def _run_extended_tool(tool_id: str, args: dict) -> Any:
    # SVG / vector studio
    if tool_id == "svg_builder":
        return _svg_builder_result(str(args.get("svg", "")), str(args.get("filename", "jarvis-vector.svg")))
    if tool_id == "svg_text_art":
        title = str(args.get("title", "Hello JARVIS"))[:100]
        subtitle = str(args.get("subtitle", "Created locally"))[:180]
        bg = str(args.get("background", "#0f2027"))
        accent = str(args.get("accent", "#5ee7ff"))
        # Validate user colours before interpolating them into SVG attributes.
        _hex_rgb(bg); _hex_rgb(accent)
        width = max(320, min(1600, int(_number(args.get("width", 800), "Width"))))
        height = max(240, min(1600, int(_number(args.get("height", 400), "Height"))))
        svg = (f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">'
               f'<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="{bg}"/><stop offset="100%" stop-color="#203a43"/></linearGradient><linearGradient id="txt"><stop offset="0%" stop-color="{accent}"/><stop offset="100%" stop-color="#b490ff"/></linearGradient></defs>'
               f'<rect width="100%" height="100%" fill="url(#bg)"/><text x="50%" y="53%" font-family="Helvetica,Arial,sans-serif" font-size="{min(160,int(height*.38))}" font-weight="bold" text-anchor="middle" fill="url(#txt)">{html.escape(title)}</text>'
               f'<text x="50%" y="76%" font-family="Helvetica,Arial,sans-serif" font-size="{min(28,int(height*.07))}" text-anchor="middle" fill="#ffffff" opacity=".75">{html.escape(subtitle)}</text></svg>')
        return _svg_builder_result(svg, "jarvis-text-art.svg")
    # QR codes
    if tool_id=="qr_generate": return _make_qr(str(args.get("value","")))
    if tool_id=="qr_wifi":
        ssid=str(args.get("ssid","")); pwd=str(args.get("password","")); sec=str(args.get("security","WPA")).upper()
        if not ssid: raise ValueError("Enter the Wi-Fi network name.")
        if sec not in ("WPA","WEP","NOPASS"): raise ValueError("Security must be WPA, WEP or nopass.")
        esc=lambda x:str(x).replace("\\","\\\\").replace(";","\\;").replace(",","\\,").replace(":","\\:").replace('"','\\"')
        payload=f'WIFI:T:{sec};S:{esc(ssid)};P:{esc(pwd)};H:{str(args.get("hidden","false")).lower() in ("true","1","yes")};;'
        return _make_qr(payload,"wifi-qr.png")
    if tool_id=="qr_vcard":
        name=str(args.get("name","")).strip()
        if not name: raise ValueError("Enter a contact name.")
        payload="BEGIN:VCARD\nVERSION:3.0\nFN:"+name+"\nTEL:"+str(args.get("phone",""))+"\nEMAIL:"+str(args.get("email",""))+"\nORG:"+str(args.get("organization",""))+"\nEND:VCARD"
        return _make_qr(payload,"contact-qr.png")
    if tool_id=="qr_email": return _make_qr("mailto:"+str(args.get("email",""))+"?subject="+quote(str(args.get("subject","")))+"&body="+quote(str(args.get("body",""))),"email-qr.png")
    if tool_id=="qr_phone": return _make_qr("tel:"+str(args.get("phone","")),"phone-qr.png")
    if tool_id=="qr_sms": return _make_qr("smsto:"+str(args.get("phone",""))+":"+str(args.get("message","")),"sms-qr.png")

    # Barcodes
    if tool_id in ("barcode_ean13_check","barcode_upca_check"):
        digits=str(args.get("digits",""))
        needed=12 if tool_id=="barcode_ean13_check" else 11
        if not digits.isdigit() or len(digits)!=needed: raise ValueError(f"Enter exactly {needed} digits.")
        total=sum(int(d)*(1 if (i%2==0) else 3) for i,d in enumerate(digits)) if needed==12 else sum(int(d)*(3 if (i%2==0) else 1) for i,d in enumerate(digits))
        return {"digits":digits,"check_digit":str((-total)%10),"complete":digits+str((-total)%10)}
    if tool_id=="barcode_validate":
        value=str(args.get("value",""))
        if not value.isdigit() or len(value) not in (12,13): raise ValueError("Enter a 12-digit UPC-A or 13-digit EAN-13 number.")
        needed=value[:-1]; expected=run_tool("barcode_ean13_check",{"digits":needed})["check_digit"] if len(value)==13 else run_tool("barcode_upca_check",{"digits":needed})["check_digit"]
        return {"value":value,"valid":value[-1]==expected,"expected_check_digit":expected,"type":"EAN-13" if len(value)==13 else "UPC-A"}
    if tool_id in ("barcode_code128","barcode_ean13","barcode_upca"):
        value=re.sub(r"\s+","",str(args.get("value","")))
        try:
            import barcode
            from barcode.writer import ImageWriter
        except ImportError as exc: raise ValueError("Barcode images need python-barcode and Pillow. Install the updated requirements.txt.") from exc
        try:
            if tool_id=="barcode_code128": cls=barcode.get_barcode_class("code128"); code=cls(value,writer=ImageWriter())
            elif tool_id=="barcode_ean13":
                if not value.isdigit() or len(value) not in (12,13): raise ValueError("EAN-13 needs 12 data digits or 13 digits including the check digit.")
                code=barcode.get_barcode_class("ean13")(value[:12],writer=ImageWriter())
            else:
                if not value.isdigit() or len(value) not in (11,12): raise ValueError("UPC-A needs 11 data digits or 12 digits including the check digit.")
                code=barcode.get_barcode_class("ean13")("0"+value[:11],writer=ImageWriter())
            buff=io.BytesIO(); code.write(buff,options={"write_text":True,"module_height":15.0})
        except ValueError: raise
        except Exception as exc: raise ValueError("Could not encode this barcode value: "+str(exc)[:120]) from exc
        result=_image_result(buff.getvalue(),"image/png",tool_id+".png"); result["barcode_value"]=value; return result

    # Colour studio
    if tool_id.startswith("color_") and tool_id in {"color_info","color_complement","color_palette","color_mix","color_shade","color_luminance"}:
        rgb=_hex_rgb(str(args.get("color",args.get("color_a","#000000"))))
        if tool_id=="color_info":
            import colorsys
            h,s,v=colorsys.rgb_to_hsv(*(x/255 for x in rgb)); r,g,b=rgb
            luminance=sum((c/12.92 if c/255<=0.04045 else ((c/255+0.055)/1.055)**2.4)*w for c,w in zip(rgb,(.2126,.7152,.0722)))
            return {"hex":_rgb_hex(rgb),"rgb":{"r":r,"g":g,"b":b},"hsv":{"h":round(h*360,1),"s":round(s*100,1),"v":round(v*100,1)},"relative_luminance":round(luminance,4)}
        if tool_id=="color_luminance":
            linear=[c/12.92 if c/255<=0.04045 else ((c/255+0.055)/1.055)**2.4 for c in rgb]
            return {"hex":_rgb_hex(rgb),"relative_luminance":sum(x*w for x,w in zip(linear,(.2126,.7152,.0722)))}
        if tool_id=="color_complement": return {"input":_rgb_hex(rgb),"complement":_rgb_hex(tuple(255-c for c in rgb))}
        if tool_id=="color_palette":
            import colorsys
            h,s,v=colorsys.rgb_to_hsv(*(c/255 for c in rgb)); palette=[]
            for shift in (-0.16,-0.08,0,0.08,0.16): palette.append(_rgb_hex(tuple(round(c*255) for c in colorsys.hsv_to_rgb((h+shift)%1,s,v))))
            return {"palette":palette}
        if tool_id=="color_mix":
            a=rgb; b=_hex_rgb(str(args.get("color_b","#FFFFFF"))); amt=_number(args.get("amount",50),"Amount")/100
            if not 0<=amt<=1: raise ValueError("Amount must be between 0 and 100.")
            return {"mixed":_rgb_hex(tuple(round(x*(1-amt)+y*amt) for x,y in zip(a,b)))}
        amount=_number(args.get("amount",0),"Amount")
        if not -100<=amount<=100: raise ValueError("Amount must be between -100 and 100.")
        factor=amount/100
        result=tuple(round(c+(255-c)*factor) if factor>=0 else round(c*(1+factor)) for c in rgb)
        return {"input":_rgb_hex(rgb),"result":_rgb_hex(result)}

    # Password / security tools
    if tool_id=="password_generate":
        import secrets,string
        length=int(_number(args.get("length",20),"Length"))
        if not 8<=length<=128: raise ValueError("Password length must be 8–128.")
        alphabet=string.ascii_letters+string.digits+("!@#$%^&*()-_=+[]{}:,.?" if str(args.get("symbols","true")).lower() in ("true","1","yes") else "")
        return {"password":"".join(secrets.choice(alphabet) for _ in range(length)),"length":length,"generated_locally":True}
    if tool_id=="password_strength":
        value=str(args.get("password","")); classes=sum([bool(re.search(r"[a-z]",value)),bool(re.search(r"[A-Z]",value)),bool(re.search(r"\d",value)),bool(re.search(r"[^A-Za-z0-9]",value))])
        score=min(4,(1 if len(value)>=8 else 0)+(1 if len(value)>=12 else 0)+(1 if len(value)>=16 else 0)+(1 if classes>=3 else 0))
        return {"length":len(value),"character_groups":classes,"score_out_of_4":score,"estimate":["Very weak","Weak","Fair","Strong","Very strong"][score],"note":"Local heuristic only; not a breach check or guarantee."}
    if tool_id=="secure_token":
        import secrets
        n=int(_number(args.get("bytes",32),"Bytes"))
        if not 16<=n<=64: raise ValueError("Use 16–64 random bytes.")
        return {"token":secrets.token_urlsafe(n),"random_bytes":n}
    if tool_id=="secure_pin":
        import secrets
        n=int(_number(args.get("digits",6),"Digits"))
        if not 4<=n<=12: raise ValueError("PIN length must be 4–12.")
        return {"pin":"".join(secrets.choice("0123456789") for _ in range(n)),"digits":n}
    if tool_id=="passphrase_generate":
        import secrets
        n=int(_number(args.get("words",5),"Words")); sep=str(args.get("separator","-"))[:4]
        if not 3<=n<=8: raise ValueError("Choose 3–8 words.")
        return {"passphrase":sep.join(secrets.choice(_WORD_BANK) for _ in range(n)),"words":n}
    if tool_id=="sha512_text": return {"algorithm":"SHA-512","hex":hashlib.sha512(str(args.get("text","")).encode()).hexdigest()}

    # File helpers
    if tool_id=="filename_sanitize":
        raw=str(args.get("filename","")); name=os.path.basename(raw).strip(); name=re.sub(r"[^A-Za-z0-9._ -]","_",name); name=re.sub(r"\s+","_",name).strip("._")
        return {"filename":name[:160] or "untitled"}
    if tool_id=="filename_parts":
        raw=os.path.basename(str(args.get("filename",""))); stem,ext=os.path.splitext(raw)
        return {"filename":raw,"stem":stem,"extension":ext.lower(),"suffixes":Path(raw).suffixes}
    if tool_id=="file_size_readable":
        n=_number(args.get("bytes",0),"Bytes")
        if n<0: raise ValueError("Bytes cannot be negative.")
        units=["B","KiB","MiB","GiB","TiB"]; x=n; i=0
        while x>=1024 and i<len(units)-1: x/=1024; i+=1
        return {"binary":f"{x:.2f} {units[i]}","decimal":f"{n/1000000:.2f} MB" if n>=1000000 else f"{n:.0f} bytes"}
    if tool_id=="text_file_stats":
        value=str(args.get("text","")); return {"lines":len(value.splitlines()),"words":len(re.findall(r"\b\w+\b",value)),"characters":len(value),"utf8_bytes":len(value.encode("utf-8"))}
    if tool_id=="base64_file_encode":
        value=str(args.get("content","")); return {"filename":str(args.get("filename","output.txt")),"mime_type":"text/plain;charset=utf-8","base64":base64.b64encode(value.encode()).decode(),"bytes":len(value.encode())}
    if tool_id=="base64_file_decode":
        try: blob=base64.b64decode(str(args.get("data","")),validate=True); value=blob.decode("utf-8")
        except Exception as exc: raise ValueError("Provide valid Base64 containing UTF-8 text.") from exc
        return {"filename":str(args.get("filename","decoded.txt")),"text":value,"bytes":len(blob)}

    # Document utilities
    if tool_id=="markdown_toc":
        lines=[]
        for line in str(args.get("text","")).splitlines():
            m=re.match(r"^\s*(#{1,6})\s+(.+?)\s*#*\s*$",line)
            if m:
                title=m.group(2).strip(); slug=re.sub(r"[^a-z0-9 -]","",title.lower()).strip().replace(" ","-")
                lines.append("  "*(len(m.group(1))-1)+f"- [{title}](#{slug})")
        return {"table_of_contents":"\n".join(lines),"headings":len(lines)}
    if tool_id=="markdown_plain":
        value=str(args.get("text","")); value=re.sub(r"```[\s\S]*?```"," ",value); value=re.sub(r"!?\[([^\]]+)\]\([^)]+\)",r"\1",value); value=re.sub(r"^\s{0,3}#{1,6}\s*","",value,flags=re.M); value=re.sub(r"[*_~`]", "", value); value=re.sub(r"^\s*>\s?","",value,flags=re.M); return {"text":value.strip()}
    if tool_id=="html_plain":
        class P(HTMLParser):
            def __init__(self): super().__init__(); self.parts=[]
            def handle_data(self,data): self.parts.append(data)
        parser=P(); parser.feed(str(args.get("html",""))); return {"text":re.sub(r"\s+"," "," ".join(parser.parts)).strip()}
    if tool_id=="markdown_table_csv":
        rows=list(csv.reader(io.StringIO(str(args.get("csv","")))))
        if not rows: raise ValueError("Enter CSV rows.")
        width=max(map(len,rows)); rows=[r+([""]*(width-len(r))) for r in rows]
        header=rows[0]; out=["| "+" | ".join(header)+" |","| "+" | ".join(["---"]*width)+" |"]
        out += ["| "+" | ".join(row)+" |" for row in rows[1:]]
        return {"markdown":"\n".join(out)}
    if tool_id=="document_page_estimate":
        words=len(re.findall(r"\b\w+\b",str(args.get("text","")))); w=int(_number(args.get("words_per_page",300),"Words per page"))
        if not 50<=w<=1000: raise ValueError("Words per page must be 50–1000.")
        return {"words":words,"estimated_pages":round(words/w,2),"full_pages":math.ceil(words/w) if words else 0}
    if tool_id=="document_heading_count":
        counts={str(i):0 for i in range(1,7)}
        for line in str(args.get("text","")).splitlines():
            m=re.match(r"^\s*(#{1,6})\s+",line)
            if m: counts[str(len(m.group(1)))]+=1
        return {"by_level":counts,"total":sum(counts.values())}

    # Image tools
    if tool_id.startswith("image_"):
        blob,mime,name=_uploaded_file(args,"image")
        try: from PIL import Image,ImageOps
        except ImportError as exc: raise ValueError("Image tools need Pillow. Install the updated requirements.txt.") from exc
        try:
            im=Image.open(io.BytesIO(blob)); im.load()
        except Exception as exc: raise ValueError("Could not decode this image file.") from exc
        if tool_id=="image_inspect": return {"filename":name,"format":im.format,"width":im.width,"height":im.height,"mode":im.mode,"bytes":len(blob),"aspect_ratio":round(im.width/im.height,5) if im.height else None}
        if tool_id=="image_base64_info": return {"filename":name,"mime_type":mime,"bytes":len(blob),"base64_characters":len(base64.b64encode(blob))}
        if tool_id=="image_resize":
            w=int(_number(args.get("width",640),"Width")); h=int(_number(args.get("height",480),"Height"))
            if not 1<=w<=4096 or not 1<=h<=4096: raise ValueError("Image dimensions must be from 1 to 4096 pixels.")
            im=im.resize((w,h),Image.Resampling.LANCZOS)
        elif tool_id=="image_thumbnail":
            edge=int(_number(args.get("max_edge",320),"Maximum edge"))
            if not 32<=edge<=2048: raise ValueError("Thumbnail edge must be 32–2048 pixels.")
            im.thumbnail((edge,edge),Image.Resampling.LANCZOS)
        elif tool_id=="image_to_jpeg":
            quality=int(_number(args.get("quality",85),"Quality"))
            if not 1<=quality<=95: raise ValueError("JPEG quality must be 1–95.")
            if im.mode not in ("RGB","L"): im=im.convert("RGB")
            buff=io.BytesIO(); im.save(buff,format="JPEG",quality=quality,optimize=True); return _image_result(buff.getvalue(),"image/jpeg",Path(name).stem+".jpg")
        elif tool_id=="image_to_png":
            buff=io.BytesIO(); im.save(buff,format="PNG",optimize=True); return _image_result(buff.getvalue(),"image/png",Path(name).stem+".png")
        buff=io.BytesIO(); im.save(buff,format="PNG"); return _image_result(buff.getvalue(),"image/png",Path(name).stem+"_output.png")

    # WAV audio utilities
    if tool_id in ("wav_inspect","wav_duration","wav_format"):
        blob,mime,name=_uploaded_file(args,"audio")
        try:
            with wave.open(io.BytesIO(blob),"rb") as w:
                info={"filename":name,"channels":w.getnchannels(),"sample_rate_hz":w.getframerate(),"frames":w.getnframes(),"sample_width_bytes":w.getsampwidth(),"duration_seconds":round(w.getnframes()/w.getframerate(),4) if w.getframerate() else 0,"compression":w.getcomptype()}
        except Exception as exc: raise ValueError("This is not a supported PCM WAV file.") from exc
        if tool_id=="wav_duration": return {"duration_seconds":info["duration_seconds"]}
