    # Statistics
    if tool_id in ("quartiles_calc","percentile_calc","variance_calc","z_score_calc"):
        if tool_id=="z_score_calc":
            val=_number(args.get("value",0),"Value"); mean=_number(args.get("mean",0),"Mean"); sd=_number(args.get("stddev",0),"Standard deviation")
            if sd<=0: raise ValueError("Standard deviation must be positive.")
            return {"z_score":(val-mean)/sd}
        vals=sorted(_number(x) for x in str(args.get("values"," ")).split(",") if x.strip())
        if not vals: raise ValueError("Enter comma-separated numbers.")
        if tool_id=="variance_calc": return {"population_variance":statistics.pvariance(vals),"sample_variance":statistics.variance(vals) if len(vals)>1 else None}
        if tool_id=="percentile_calc":
            p=_number(args.get("percentile",50),"Percentile")
            if not 0<=p<=100: raise ValueError("Percentile must be 0–100.")
            k=(len(vals)-1)*p/100; lo=math.floor(k); hi=math.ceil(k); x=vals[lo]+(vals[hi]-vals[lo])*(k-lo)
            return {"percentile":p,"value":x}
        mid=len(vals)//2; lower=vals[:mid]; upper=vals[(mid+1 if len(vals)%2 else mid):]
        return {"min":vals[0],"q1":statistics.median(lower) if lower else vals[0],"median":statistics.median(vals),"q3":statistics.median(upper) if upper else vals[-1],"max":vals[-1]}
    if tool_id in ("covariance_calc","linear_regression"):
        xs=[_number(x) for x in str(args.get("x_values"," ")).split(",") if x.strip()]; ys=[_number(x) for x in str(args.get("y_values"," ")).split(",") if x.strip()]
        if len(xs)!=len(ys) or len(xs)<2: raise ValueError("Enter matching X and Y lists with at least two values.")
        mx=statistics.mean(xs); my=statistics.mean(ys); cov=sum((x-mx)*(y-my) for x,y in zip(xs,ys))/len(xs)
        if tool_id=="covariance_calc": return {"population_covariance":cov}
        vx=sum((x-mx)**2 for x in xs); vy=sum((y-my)**2 for y in ys)
