            if not scores or len(scores)!=len(weights) or any(not 0<=x<=100 for x in scores) or any(x<0 for x in weights) or sum(weights)==0: raise ValueError("Provide matching scores (0–100) and non-negative weights.")
            return {"weighted_average":sum(s*w for s,w in zip(scores,weights))/sum(weights)}
