TEMPERATURE_TO_KELVIN = {
    "celsius": lambda x: x + 273.15,
    "fahrenheit": lambda x: (x - 32.0) * 5.0/9.0 + 273.15,
    "kelvin": lambda x: x,
    "rankine": lambda x: x * 5.0/9.0,
}
TEMPERATURE_FROM_KELVIN = {
    "celsius": lambda k: k - 273.15,
    "fahrenheit": lambda k: (k - 273.15) * 9.0/5.0 + 32.0,
    "kelvin": lambda k: k,
    "rankine": lambda k: k * 9.0/5.0,
}

TOOL_CONVERSIONS: dict[str, tuple[str, str, str]] = {}
CONVERSION_CATEGORY_LABELS = {
    "length": "Length", "mass": "Mass", "volume": "Volume", "area": "Area",
    "speed": "Speed", "time": "Time", "pressure": "Pressure", "energy": "Energy",
    "power": "Power", "digital_data": "Digital data", "temperature": "Temperature",
    "angle": "Angle", "frequency": "Frequency", "acceleration": "Acceleration",
    "absorbed_dose": "Radiation dose",
}

def _conversion_specs() -> list[dict]:
    specs = []
    for group, units in UNIT_GROUPS.items():
        for from_id, (from_name, from_symbol, _) in units.items():
            for to_id, (to_name, to_symbol, _) in units.items():
                if from_id == to_id:
                    continue
                tool_id = f"convert_{group}_{from_id}_to_{to_id}"
                TOOL_CONVERSIONS[tool_id] = (group, from_id, to_id)
                category = group
                specs.append({
                    "id": tool_id,
                    "category": category,
                    "name": f"{from_name} to {to_name}",
                    "description": f"Convert a value from {from_name} ({from_symbol}) to {to_name} ({to_symbol}).",
                    "fields": [_field("value", f"Value ({from_symbol})", "number", 1)],
                    "example": json.dumps({"value": 1}),
                })
    return specs

def _run_conversion(tool_id: str, args: dict) -> dict:
    group, from_id, to_id = TOOL_CONVERSIONS[tool_id]
    value = _number(args.get("value", 0), "Value")
    if group == "temperature":
        kelvin = TEMPERATURE_TO_KELVIN[from_id](value)
        if kelvin < 0:
            raise ValueError("Temperature is below absolute zero.")
        result = TEMPERATURE_FROM_KELVIN[to_id](kelvin)
    else:
        units = UNIT_GROUPS[group]
        result = value * units[from_id][2] / units[to_id][2]
    if not math.isfinite(result):
        raise ValueError("The converted value is outside the supported numeric range.")
    # Keep a useful number of significant digits while avoiding noisy float tails.
    result = float(f"{result:.13g}")
    from_name, from_symbol, _ = UNIT_GROUPS[group][from_id]
    to_name, to_symbol, _ = UNIT_GROUPS[group][to_id]
    return {
        "input": value,
        "from": from_name,
        "to": to_name,
        "result": result,
        "expression": f"{value:g} {from_symbol} = {result:g} {to_symbol}",
    }


