def _persistent_tool_specs() -> list[dict]:
    """Expose approved persistent workflow tools in the normal JARVIS catalogue."""
    manager = globals().get("SELF_UPGRADE_MANAGER")
    if manager is None:
        return []
    rows = []
    for tool in manager.tools():
        fields = []
        example = {}
        for item in tool.get("input_fields", []):
            name = str(item.get("name", "input"))
            fields.append({"name":name, "label":str(item.get("description") or name.replace("_", " ").title()),
                           "type":"textarea", "default":"", "required":bool(item.get("required", False))})
            example[name] = ""
        rows.append({"id":tool["name"], "category":"custom_extensions", "name":tool.get("name", "Custom tool").replace("custom_", "").replace("_", " ").title(),
                     "description":tool.get("description", "Persistent custom tool"), "fields":fields,
                     "example":json.dumps(example, ensure_ascii=False), "custom":True})
    return rows


def _all_tool_specs() -> list[dict]:
    expansion = globals().get("EXPANSION_MANAGER")
    extra = expansion.tool_specs() if expansion is not None else []
    return list(TOOL_SPECS) + _persistent_tool_specs() + extra


def _as_text(args: dict) -> str:
    return str(args.get("text", ""))[:50000]


def _number(value: Any, label: str = "Number") -> float:
    try:
        n = float(value)
    except (TypeError, ValueError):
        raise ValueError(f"{label} must be a number.")
    if not math.isfinite(n):
        raise ValueError(f"{label} must be finite.")
    return n


_ALLOWED_BINOPS = {
    ast.Add: lambda a, b: a + b, ast.Sub: lambda a, b: a - b,
    ast.Mult: lambda a, b: a * b, ast.Div: lambda a, b: a / b,
    ast.FloorDiv: lambda a, b: a // b, ast.Mod: lambda a, b: a % b,
    ast.Pow: lambda a, b: a ** b,
}
_ALLOWED_UNARY = {ast.UAdd: lambda x: x, ast.USub: lambda x: -x}


def _safe_math(expression: str) -> float:
    if len(expression) > 160:
        raise ValueError("Expression is too long.")
    try:
        root = ast.parse(expression, mode="eval")
    except SyntaxError as exc:
        raise ValueError("That expression is not valid arithmetic.") from exc
    def walk(node):
        if isinstance(node, ast.Expression): return walk(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
            return node.value
        if isinstance(node, ast.BinOp) and type(node.op) in _ALLOWED_BINOPS:
            left, right = walk(node.left), walk(node.right)
            if isinstance(node.op, ast.Pow) and (abs(right) > 12 or abs(left) > 1e6):
                raise ValueError("Power is limited to safe values.")
            if isinstance(node.op, (ast.Div, ast.FloorDiv, ast.Mod)) and right == 0:
                raise ValueError("Cannot divide by zero.")
            result = _ALLOWED_BINOPS[type(node.op)](left, right)
            if not math.isfinite(float(result)) or abs(result) > 1e100:
                raise ValueError("Result is too large.")
            return result
        if isinstance(node, ast.UnaryOp) and type(node.op) in _ALLOWED_UNARY:
            return _ALLOWED_UNARY[type(node.op)](walk(node.operand))
        raise ValueError("Only basic arithmetic is allowed: + - * / // % ** and parentheses.")
    return float(walk(root))


def _flatten_json(data: Any, prefix: str = "") -> dict:
    out = {}
    if isinstance(data, dict):
        for key, value in data.items():
            path = f"{prefix}.{key}" if prefix else str(key)
            if isinstance(value, (dict, list)): out.update(_flatten_json(value, path))
            else: out[path] = value
    elif isinstance(data, list):
        for index, value in enumerate(data):
            path = f"{prefix}[{index}]"
            if isinstance(value, (dict, list)): out.update(_flatten_json(value, path))
            else: out[path] = value
    else:
        out[prefix or "value"] = data
    return out


class _PublicPageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.title_parts=[]; self.text_parts=[]; self.links=[]
        self._in_title=False; self._skip=0
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if tag.lower()=="title": self._in_title=True
        if tag.lower() in ("script","style","noscript","svg","canvas"): self._skip+=1
        if tag.lower()=="a" and attrs.get("href"):
            self.links.append((attrs.get("href"), attrs.get("title") or ""))
    def handle_endtag(self, tag):
        if tag.lower()=="title": self._in_title=False
        if tag.lower() in ("script","style","noscript","svg","canvas") and self._skip: self._skip-=1
    def handle_data(self, data):
        value=data.strip()
        if not value: return
        if self._in_title: self.title_parts.append(value)
        if not self._skip: self.text_parts.append(value)


def _validate_public_url(raw: str) -> str:
    value=str(raw or "").strip()
    parsed=urlparse(value)
    if parsed.scheme not in ("http","https") or not parsed.hostname:
        raise ValueError("Enter a full public http:// or https:// URL.")
    if parsed.username or parsed.password:
        raise ValueError("URLs containing embedded usernames or passwords are not allowed.")
    host=parsed.hostname.strip("[]").lower()
    if host in ("localhost",) or host.endswith((".localhost", ".local", ".internal")):
        raise ValueError("Local or private network addresses are blocked.")
    try:
        ip=ipaddress.ip_address(host)
        if not ip.is_global: raise ValueError("Private or reserved IP addresses are blocked.")
    except ValueError as exc:
        if "blocked" in str(exc): raise
        try:
            addresses={item[4][0] for item in socket.getaddrinfo(host, parsed.port or (443 if parsed.scheme=="https" else 80), type=socket.SOCK_STREAM)}
        except OSError as dns_exc:
            raise ValueError("The website hostname could not be resolved.") from dns_exc
        if not addresses or any(not ipaddress.ip_address(addr).is_global for addr in addresses):
            raise ValueError("The website resolves to a private or reserved address and was blocked.")
    return value


def _fetch_public_url(raw: str, max_bytes: int = 1_000_000) -> dict:
    current=_validate_public_url(raw)
    headers={"User-Agent":"JARVIS-Android-Assistant/1.9 (+public-page-reader)","Accept":"text/html,text/plain,application/xhtml+xml,*/*;q=0.5"}
    for _ in range(4):
        current=_validate_public_url(current)
        try:
            response=requests.get(current,headers=headers,timeout=(8,18),allow_redirects=False,stream=True)
        except requests.RequestException as exc:
            raise ValueError(f"Could not reach the public page: {exc.__class__.__name__}.") from exc
        if response.status_code in (301,302,303,307,308):
            location=response.headers.get("Location")
            response.close()
            if not location: raise ValueError("The website returned a redirect without a location.")
            current=urljoin(current,location)
            continue
        if response.status_code>=400:
            status=response.status_code; response.close()
            raise ValueError(f"The website returned HTTP {status}.")
        content_type=response.headers.get("Content-Type","").lower()
        pieces=[]; size=0
        try:
            for chunk in response.iter_content(65536):
                if not chunk: continue
                size+=len(chunk)
                if size>max_bytes: raise ValueError("The page is larger than the 1 MB reading limit.")
                pieces.append(chunk)
        finally:
            response.close()
        raw_bytes=b"".join(pieces)
        encoding=response.encoding or "utf-8"
        try: body=raw_bytes.decode(encoding,errors="replace")
        except LookupError: body=raw_bytes.decode("utf-8",errors="replace")
        return {"url":current,"status":response.status_code,"content_type":content_type,"body":body}
    raise ValueError("The website redirected too many times.")


def _tavily_search(query: str, cfg: dict, topic: str = "general", max_results: int = 5) -> dict:
    key=str(cfg.get("tavily_key", "")).strip()
    if not key: raise ValueError("Tavily API key is not configured. Add it in Voice & AI settings, or configure a Gemini API key for Google Search fallback.")
    query=str(query or "").strip()[:500]
    if not query: raise ValueError("Enter a search query.")
    max_results=max(1,min(int(max_results),10))
    payload={"api_key":key,"query":query,"topic":"news" if topic=="news" else "general","search_depth":"basic","max_results":max_results,"include_answer":False,"include_raw_content":False}
    try: response=requests.post("https://api.tavily.com/search",json=payload,timeout=(10,35))
    except requests.RequestException as exc: raise ValueError(f"Tavily connection error: {exc.__class__.__name__}.") from exc
    if response.status_code>=400:
        try: detail=response.json().get("detail",response.json().get("error",f"HTTP {response.status_code}"))
        except Exception: detail=f"HTTP {response.status_code}"
        raise ValueError(f"Tavily search failed: {str(detail)[:220]}")
    data=response.json(); results=[]
    for item in data.get("results",[])[:max_results]:
        url=str(item.get("url", ""))
        if not url.startswith(("https://","http://")): continue
        results.append({"title":str(item.get("title", "Untitled"))[:240],"url":url,"content":str(item.get("content", ""))[:3000],"score":item.get("score"),"published_date":item.get("published_date")})
    return {"query":query,"provider":"Tavily","results":results,"answer":data.get("answer"),"response_time":data.get("response_time")}


def _google_grounded_search(query: str, cfg: dict, max_results: int = 5) -> dict:
    key=str(cfg.get("gemini_key", "")).strip()
    if not key: raise ValueError("Configure a Tavily key or Gemini API key to search the web.")
    model=str(cfg.get("gemini_chat_model", "gemini-3.8-flash")).strip() or "gemini-3.8-flash"
    payload={"model":model,"input":str(query or "").strip()[:500],"tools":[{"type":"google_search"}]}
    try: response=requests.post("https://generativelanguage.googleapis.com/v1beta/interactions",headers={"x-goog-api-key":key,"Content-Type":"application/json"},json=payload,timeout=(12,70))
    except requests.RequestException as exc: raise ValueError(f"Google Search connection error: {exc.__class__.__name__}.") from exc
    if response.status_code>=400:
        try: detail=response.json().get("error",{}).get("message",f"HTTP {response.status_code}")
        except Exception: detail=f"HTTP {response.status_code}"
        raise ValueError(f"Gemini Google Search failed: {str(detail)[:240]}")
    data=response.json(); text=data.get("output_text","")
    sources=[]
    def walk(node):
        if isinstance(node,dict):
            if node.get("type")=="url_citation":
                url=node.get("url"); title=node.get("title") or url
                if url and str(url).startswith("https://"): sources.append({"title":str(title)[:200],"url":str(url)})
            web=node.get("web")
            if isinstance(web,dict) and web.get("uri"):
                url=web.get("uri")
                if str(url).startswith("https://"): sources.append({"title":str(web.get("title") or url)[:200],"url":str(url)})
            for value in node.values(): walk(value)
        elif isinstance(node,list):
            for value in node: walk(value)
    walk(data.get("output",data))
    if not text:
        fragments=[]
        def find_text(node):
            if isinstance(node,dict):
                if node.get("type")=="text" and isinstance(node.get("text"),str): fragments.append(node["text"])
                for value in node.values(): find_text(value)
            elif isinstance(node,list):
                for value in node: find_text(value)
        find_text(data.get("output",[])); text="\n".join(fragments)
    dedup=[]; seen=set()
    for src in sources:
        if src["url"] not in seen: seen.add(src["url"]); dedup.append(src)
    return {"query":query,"provider":"Google Search via Gemini","answer":str(text)[:12000],"results":dedup[:max_results]}


def _web_search(query: str, cfg: dict, topic: str = "general", max_results: int = 5) -> dict:
    if str(cfg.get("tavily_key", "")).strip():
        return _tavily_search(query,cfg,topic,max_results)
    return _google_grounded_search(query,cfg,max_results)


def _decode_image(image: Any) -> dict | None:
    if image is None: return None
    if not isinstance(image,dict): raise ValueError("Image attachment must be an image object.")
    mime=str(image.get("mime_type", "")).lower().strip()
    if mime not in ("image/jpeg","image/png","image/webp","image/gif"):
        raise ValueError("Use a JPG, PNG, WebP or GIF image.")
    raw=str(image.get("data", "")).strip()
    if raw.startswith("data:") and "," in raw: raw=raw.split(",",1)[1]
    if not raw: raise ValueError("The selected image is empty.")
    if len(raw)>8_500_000: raise ValueError("Image is too large. Choose a smaller image (maximum 6 MB).")
    try: blob=base64.b64decode(raw,validate=True)
    except Exception as exc: raise ValueError("Image data is not valid Base64.") from exc
    if not blob or len(blob)>6*1024*1024: raise ValueError("Image is too large. Maximum size is 6 MB.")
    signatures={"image/jpeg":blob.startswith(b"\xff\xd8\xff"),"image/png":blob.startswith(b"\x89PNG\r\n\x1a\n"),"image/gif":blob.startswith((b"GIF87a",b"GIF89a")),"image/webp":len(blob)>12 and blob[:4]==b"RIFF" and blob[8:12]==b"WEBP"}
    if not signatures.get(mime,False): raise ValueError("The file content does not match its image type.")
    return {"mime_type":mime,"data":raw,"bytes":len(blob)}


def _image_dimensions(blob: bytes, mime: str) -> tuple[int|None,int|None]:
    if mime=="image/png" and len(blob)>=24: return struct.unpack(">II",blob[16:24])
    if mime=="image/gif" and len(blob)>=10: return struct.unpack("<HH",blob[6:10])
    if mime=="image/webp" and len(blob)>=30:
        kind=blob[12:16]
        if kind==b"VP8X": return (1+int.from_bytes(blob[24:27],"little"),1+int.from_bytes(blob[27:30],"little"))
    if mime=="image/jpeg":
        i=2
        while i+9<len(blob):
            if blob[i]!=0xFF: i+=1; continue
            marker=blob[i+1]; i+=2
            if marker in (0xD8,0xD9,0x01) or 0xD0<=marker<=0xD7: continue
            if i+2>len(blob): break
            length=int.from_bytes(blob[i:i+2],"big")
            if marker in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF) and i+7<len(blob):
                return int.from_bytes(blob[i+5:i+7],"big"),int.from_bytes(blob[i+3:i+5],"big")
            if length<2: break
            i+=length
    return None,None


def _run_ai_utility(tool_id: str, args: dict) -> dict:
    if tool_id == "prompt_builder":
        role=str(args.get("role", "Helpful assistant")).strip() or "Helpful assistant"
        task=str(args.get("task", "")).strip()
        if not task: raise ValueError("Enter the task for the prompt.")
        context=str(args.get("context", "")).strip()
        constraints=str(args.get("constraints", "")).strip()
        fmt=str(args.get("format", "Clear structured answer")).strip()
        prompt=f"You are {role}.\n\nTASK\n{task}"
        if context: prompt += "\n\nCONTEXT\n"+context
        if constraints: prompt += "\n\nCONSTRAINTS\n"+constraints
        prompt += "\n\nOUTPUT FORMAT\n"+fmt+"\n\nBe accurate. State uncertainty. Do not invent sources or claim actions you did not perform."
        return {"prompt":prompt}
    if tool_id == "checklist_from_text":
        items=[x.strip(" -\t") for x in re.split(r"[\n;]+",str(args.get("text", ""))) if x.strip(" -\t")]
        return {"count":len(items),"checklist":"\n".join(f"- [ ] {x}" for x in items)}
    if tool_id == "task_breakdown":
        goal=str(args.get("goal", "")).strip()
        if not goal: raise ValueError("Enter a goal.")
        milestones=[x.strip(" -\t") for x in re.split(r"[\n;]+",str(args.get("milestones", ""))) if x.strip(" -\t")]
        if not milestones: milestones=["Define the goal and success criteria", "Gather the information or materials", "Complete the main work", "Review the result", "Make final corrections"]
        return {"goal":goal,"steps":[{"step":i+1,"task":x} for i,x in enumerate(milestones)]}
    if tool_id == "response_outline":
        topic=str(args.get("topic", "")).strip()
        sections=[x.strip() for x in str(args.get("sections", "Introduction,Main points,Conclusion")).split(",") if x.strip()]
        if not topic: raise ValueError("Enter a topic.")
        return {"outline":"# "+topic+"\n"+"\n".join(f"## {x}\n- " for x in sections)}
    if tool_id == "meeting_action_items":
        notes=str(args.get("notes", ""))
        found=[]
        for line in notes.splitlines():
            if re.search(r"\b(action|todo|to-do|follow[- ]?up|owner|due)\b",line,re.I):
                found.append(line.strip(" -\t"))
        return {"action_items":found,"count":len(found)}
    if tool_id == "json_array_filter":
        data=json.loads(str(args.get("json", "[]")))
        if not isinstance(data,list): raise ValueError("JSON must be an array.")
        key=str(args.get("key", "")); op=str(args.get("operator", "eq")).lower(); val=str(args.get("value", ""))
        if op not in ("eq","ne","contains","gt","lt"): raise ValueError("Operator must be eq, ne, contains, gt or lt.")
        def match(item):
            actual=item.get(key) if isinstance(item,dict) else None
            if op=="eq": return str(actual)==val
            if op=="ne": return str(actual)!=val
            if op=="contains": return val.casefold() in str(actual).casefold()
            try: a=float(actual); b=float(val)
            except (TypeError,ValueError): return False
            return a>b if op=="gt" else a<b
        rows=[x for x in data if match(x)]
        return {"count":len(rows),"items":rows}
    if tool_id == "json_array_sort":
        data=json.loads(str(args.get("json", "[]")))
        if not isinstance(data,list): raise ValueError("JSON must be an array.")
        key=str(args.get("key", "")); desc=str(args.get("descending", "false")).lower() in ("true","1","yes")
        return {"items":sorted(data,key=lambda x:(x.get(key) is None, str(x.get(key,"")) if isinstance(x,dict) else str(x)),reverse=desc)}
    if tool_id == "json_array_unique":
        data=json.loads(str(args.get("json", "[]")))
        if not isinstance(data,list): raise ValueError("JSON must be an array.")
        output=[]; seen=set()
        for item in data:
            key=json.dumps(item,sort_keys=True,ensure_ascii=False,default=str)
            if key not in seen: seen.add(key); output.append(item)
        return {"items":output,"removed":len(data)-len(output)}
    if tool_id == "json_path_get":
        data=json.loads(str(args.get("json", "{}")))
        path=str(args.get("path", ""))
        tokens=re.findall(r"(?:^|\.)([^.\[\]]+)|\[(\d+)\]",path)
        if not path or not tokens: raise ValueError("Enter a path such as user.name or items[0].id.")
        value=data
        for name,index in tokens:
            if name:
                if not isinstance(value,dict) or name not in value: raise ValueError("Path not found: "+path)
                value=value[name]
            else:
                if not isinstance(value,list) or int(index)>=len(value): raise ValueError("Array index not found: "+path)
                value=value[int(index)]
        return {"path":path,"value":value}
    if tool_id in ("csv_validate","csv_column_extract","csv_filter_rows","csv_to_tsv_plus"):
        raw=str(args.get("csv", ""))
        try:
            reader=csv.DictReader(io.StringIO(raw,newline=""))
            headers=reader.fieldnames or []
            rows=list(reader)
        except Exception as exc: raise ValueError("Could not parse CSV: "+str(exc)[:120]) from exc
        if tool_id=="csv_validate":
            malformed=sum(1 for row in rows if None in row or any(v is None for k,v in row.items() if k is not None))
            return {"valid":bool(headers) and malformed==0,"headers":headers,"rows":len(rows),"columns":len(headers),"malformed_rows":malformed}
        if tool_id=="csv_column_extract":
            col=str(args.get("column", ""))
            if col not in headers: raise ValueError("Column not found in CSV header.")
            return {"column":col,"values":[r.get(col,"") for r in rows]}
        if tool_id=="csv_filter_rows":
            col=str(args.get("column", "")); value=str(args.get("value", ""))
            if col not in headers: raise ValueError("Column not found in CSV header.")
            selected=[r for r in rows if str(r.get(col,""))==value]
            out=io.StringIO(newline=""); writer=csv.DictWriter(out,fieldnames=headers); writer.writeheader(); writer.writerows(selected)
            return {"count":len(selected),"csv":out.getvalue()}
        out=io.StringIO(newline=""); writer=csv.writer(out,delimiter="\t"); writer.writerow(headers)
        for row in rows: writer.writerow([row.get(k,"") for k in headers])
        return {"tsv":out.getvalue()}
    if tool_id == "base64_encode_text":
        text=str(args.get("text", "")); return {"base64":base64.b64encode(text.encode("utf-8")).decode("ascii")}
    if tool_id == "base64_decode_text":
        try: return {"text":base64.b64decode(str(args.get("data", "")),validate=True).decode("utf-8")}
        except Exception as exc: raise ValueError("Enter valid Base64 containing UTF-8 text.") from exc
    if tool_id == "url_encode_text": return {"encoded":quote(str(args.get("text", "")),safe="")}
    if tool_id == "url_decode_text": return {"decoded":unquote(str(args.get("text", "")))}
    if tool_id == "uuid_generate":
        count=int(_number(args.get("count", 1),"Count"))
        if not 1<=count<=20: raise ValueError("Count must be from 1 to 20.")
        return {"uuids":[str(uuid.uuid4()) for _ in range(count)]}
    if tool_id == "uuid_validate":
        value=str(args.get("value", ""))
        try: parsed=uuid.UUID(value); valid=True
        except (ValueError,AttributeError,TypeError): parsed=None; valid=False
        return {"valid":valid,"normalized":str(parsed) if parsed else None}
    if tool_id == "email_validate":
        value=str(args.get("email", "")).strip()
        valid=bool(re.fullmatch(r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+",value))
        return {"email":value,"format_valid":valid,"note":"Format check only; this does not verify mailbox ownership or delivery."}
    if tool_id in ("url_parse","url_remove_tracking","domain_extract","robots_txt_url"):
        raw=str(args.get("url", "")).strip()
        if tool_id=="robots_txt_url" and raw and not re.match(r"^https?://",raw,re.I): raw="https://"+raw
        parsed=urlparse(raw)
        if parsed.scheme not in ("http","https") or not parsed.hostname: raise ValueError("Enter a valid HTTP or HTTPS URL.")
        host=parsed.hostname.lower()
        if tool_id=="domain_extract": return {"domain":host}
        if tool_id=="robots_txt_url": return {"robots_txt":f"{parsed.scheme}://{parsed.netloc}/robots.txt"}
        if tool_id=="url_parse": return {"scheme":parsed.scheme,"hostname":host,"port":parsed.port,"path":parsed.path,"query":parsed.query,"fragment":parsed.fragment}
        from urllib.parse import parse_qsl,urlencode,urlunparse
        kept=[(k,v) for k,v in parse_qsl(parsed.query,keep_blank_values=True) if not (k.lower().startswith("utm_") or k.lower() in ("fbclid","gclid","mc_cid","mc_eid","ref_src"))]
        return {"url":urlunparse((parsed.scheme,parsed.netloc,parsed.path,parsed.params,urlencode(kept,doseq=True),parsed.fragment))}
    if tool_id == "url_query_builder":
        raw=str(args.get("url", "")).strip(); parsed=urlparse(raw)
        if parsed.scheme not in ("http","https") or not parsed.netloc: raise ValueError("Enter a valid HTTP or HTTPS URL.")
        params=json.loads(str(args.get("params", "{}")))
        if not isinstance(params,dict): raise ValueError("Parameters must be a JSON object.")
        from urllib.parse import parse_qsl,urlencode,urlunparse
        merged=dict(parse_qsl(parsed.query,keep_blank_values=True)); merged.update({str(k):str(v) for k,v in params.items()})
        return {"url":urlunparse((parsed.scheme,parsed.netloc,parsed.path,parsed.params,urlencode(merged),parsed.fragment))}
    if tool_id == "timestamp_iso_utc":
        value=_number(args.get("timestamp",0),"Timestamp")
        if abs(value)>100_000_000_000: value/=1000
        try: stamp=dt.datetime.fromtimestamp(value,dt.timezone.utc).isoformat()
        except (OverflowError,OSError,ValueError) as exc: raise ValueError("Timestamp is outside supported range.") from exc
        return {"utc":stamp,"unix_seconds":value}
    if tool_id == "iso_to_timestamp":
        raw=str(args.get("value", "")).strip()
        try: date=dt.datetime.fromisoformat(raw.replace("Z","+00:00"))
        except ValueError as exc: raise ValueError("Enter an ISO-8601 date/time.") from exc
        if date.tzinfo is None: date=date.replace(tzinfo=dt.timezone.utc)
        return {"unix_seconds":date.timestamp(),"utc":date.astimezone(dt.timezone.utc).isoformat()}
    if tool_id == "date_add_days":
        date=dt.date.fromisoformat(str(args.get("date", "")))
        days=int(_number(args.get("days",0),"Days"))
        if abs(days)>365000: raise ValueError("Days must be within ±365,000.")
        result=date+dt.timedelta(days=days)
        return {"date":result.isoformat(),"days_added":days}
    if tool_id == "date_difference_days":
        start=dt.date.fromisoformat(str(args.get("start", ""))); end=dt.date.fromisoformat(str(args.get("end", "")))
        return {"start":start.isoformat(),"end":end.isoformat(),"difference_days":(end-start).days,"absolute_days":abs((end-start).days)}
    if tool_id == "calendar_week_info":
        date=dt.date.fromisoformat(str(args.get("date", ""))); iso=date.isocalendar()
        return {"date":date.isoformat(),"iso_year":iso.year,"iso_week":iso.week,"weekday":iso.weekday,"day_of_year":date.timetuple().tm_yday}
    if tool_id == "pomodoro_plan_plus":
        cycles=int(_number(args.get("cycles",4),"Cycles")); focus=int(_number(args.get("focus_minutes",25),"Focus minutes")); short=int(_number(args.get("short_break",5),"Short break")); long=int(_number(args.get("long_break",15),"Long break"))
        if not 1<=cycles<=8 or not 5<=focus<=120 or not 1<=short<=30 or not 1<=long<=60: raise ValueError("Use 1–8 cycles, 5–120 focus minutes and valid break lengths.")
        plan=[]
        for i in range(cycles):
            plan.append({"type":"focus","minutes":focus,"cycle":i+1})
            if i<cycles-1: plan.append({"type":"long_break" if (i+1)%4==0 else "short_break","minutes":long if (i+1)%4==0 else short,"cycle":i+1})
        return {"schedule":plan,"total_minutes":sum(x["minutes"] for x in plan)}
    if tool_id == "study_plan":
        topics=[x.strip() for x in str(args.get("topics", "")).splitlines() if x.strip()]
        total=int(_number(args.get("total_minutes",60),"Total minutes")); br=int(_number(args.get("break_minutes",5),"Break minutes"))
        if not topics: raise ValueError("Enter at least one topic.")
        if not 10<=total<=600 or not 0<=br<=30: raise ValueError("Use 10–600 total minutes and 0–30 minute breaks.")
        work=max(1,total-br*(len(topics)-1)); base=work//len(topics); rem=work%len(topics)
        slots=[{"topic":t,"minutes":base+(1 if i<rem else 0)} for i,t in enumerate(topics)]
        return {"study_slots":slots,"break_minutes_between_topics":br,"total_minutes":total}
    if tool_id == "weekly_goal_tracker":
        goal=str(args.get("goal", "")).strip(); days=int(_number(args.get("days",5),"Days"))
        if not goal: raise ValueError("Enter a weekly goal.")
        if not 1<=days<=7: raise ValueError("Target days must be 1–7.")
        return {"goal":goal,"target_days":days,"tracker":"\n".join(f"- [ ] Day {i+1}" for i in range(7))}
    if tool_id == "decision_score":
        options=json.loads(str(args.get("options", "[]"))); weights=json.loads(str(args.get("weights", "{}")))
        if not isinstance(options,list) or not isinstance(weights,dict) or not options: raise ValueError("Options must be a non-empty JSON array and weights a JSON object.")
        total=sum(max(0.0,float(v)) for v in weights.values())
        if total<=0: raise ValueError("At least one weight must be greater than zero.")
        results=[]
        for item in options:
            if not isinstance(item,dict): continue
            scores=item.get("scores",{}); score=sum(max(0.0,float(w))/total*float(scores.get(k,0)) for k,w in weights.items())
            results.append({"name":str(item.get("name","Option")),"weighted_score":round(score,4)})
        results.sort(key=lambda x:x["weighted_score"],reverse=True)
        return {"ranking":results,"note":"Scores depend on the values and weights supplied."}
    if tool_id == "http_status_explain":
        code=int(_number(args.get("status",200),"HTTP status"))
        labels={200:"OK — request succeeded",201:"Created — resource created",204:"No Content — succeeded with no response body",301:"Moved Permanently — use the new URL",302:"Found — temporary redirect",304:"Not Modified — cached copy can be used",400:"Bad Request — request format or data is invalid",401:"Unauthorized — authentication is required or invalid",403:"Forbidden — server refuses access",404:"Not Found — resource does not exist",408:"Request Timeout — server timed out",409:"Conflict — request conflicts with current state",422:"Unprocessable Content — data could not be processed",429:"Too Many Requests — rate limit reached",500:"Internal Server Error — server failed",502:"Bad Gateway — upstream server returned an invalid response",503:"Service Unavailable — server is temporarily unavailable",504:"Gateway Timeout — upstream did not respond in time"}
        return {"status":code,"explanation":labels.get(code,"Uncommon or extension HTTP status code; consult the server's documentation.")}
    raise ValueError("Unknown AI utility.")


def run_tool(tool_id: str, args: dict, cfg: dict | None = None) -> Any:
    cfg = cfg or {}
    expansion = globals().get("EXPANSION_MANAGER")
    if expansion is not None and expansion.has_local_tool(tool_id):
        return expansion.run_local_tool(tool_id, args, cfg)
    if tool_id not in TOOL_IDS:
        raise ValueError("Unknown tool. Refresh the tools list and try again.")
    if tool_id in TOOL_CONVERSIONS:
        return _run_conversion(tool_id, args)
    if tool_id in EXTENDED_TOOL_IDS:
        return _run_extended_tool(tool_id, args)
    if tool_id in AI_UTILITY_TOOL_IDS:
        return _run_ai_utility(tool_id, args)
    text = _as_text(args)
    words = re.findall(r"\b[\w']+\b", text, flags=re.UNICODE)
    if tool_id == "word_count": return {"words": len(words)}
    if tool_id == "text_stats":
        sentences = len(re.findall(r"[.!?]+(?:\s|$)", text)) or (1 if text.strip() else 0)
        return {"words":len(words),"characters":len(text),"characters_without_spaces":len(re.sub(r"\s", "", text)),"sentences":sentences,"estimated_reading_minutes":round(len(words)/220, 2)}
    if tool_id == "char_count": return {"characters":len(text),"without_spaces":len(re.sub(r"\s", "", text)),"bytes_utf8":len(text.encode("utf-8"))}
    if tool_id == "clean_text": return {"text":re.sub(r"\n\s*\n+", "\n", re.sub(r"[ \t]+", " ", text)).strip()}
    if tool_id == "reverse_text": return {"text":text[::-1]}
    if tool_id == "slugify": return {"slug":re.sub(r"-+", "-", re.sub(r"[^a-z0-9]+", "-", text.lower())).strip("-")}
    if tool_id == "upper": return {"text":text.upper()}
    if tool_id == "lower": return {"text":text.lower()}
    if tool_id == "title_case": return {"text":text.title()}
    if tool_id == "find_replace":
        find = str(args.get("find", ""))
        if not find: raise ValueError("Enter text to find.")
        result = text.replace(find, str(args.get("replace", "")))
        return {"text":result,"replacements":text.count(find)}
    if tool_id == "split_lines": return {"lines":[line for line in text.splitlines() if line.strip()],"count":len([line for line in text.splitlines() if line.strip()])}
    if tool_id == "word_frequency":
        freq = Counter(w.lower() for w in words if len(w) > 1)
        return {"top_words":[{"word":w,"count":n} for w,n in freq.most_common(15)]}
    if tool_id == "reading_time":
        count=len(words)
        return {"words":count,"minutes":round(count/220,2),"display":f"About {max(1, math.ceil(count/220))} min" if count else "Less than a minute"}
    if tool_id in ("json_pretty", "json_minify", "json_flatten", "json_validate", "json_get"):
        parsed=json.loads(text)
        if tool_id == "json_pretty": return {"json":json.dumps(parsed,ensure_ascii=False,indent=2)}
        if tool_id == "json_minify": return {"json":json.dumps(parsed,ensure_ascii=False,separators=(",",":"))}
        if tool_id == "json_flatten": return {"flattened":_flatten_json(parsed)}
        if tool_id == "json_validate": return {"valid":True,"type":type(parsed).__name__}
        path=str(args.get("path", "")).strip()
        if not path: raise ValueError("Enter a key path, for example user.name.")
        current=parsed
        for part in re.split(r"\.(?![^\[]*\])",path):
            m=re.fullmatch(r"([^\[]+)(?:\[(\d+)\])?",part)
            if not m: raise ValueError("Invalid JSON path.")
            key,index=m.group(1),m.group(2)
            if isinstance(current,dict) and key in current: current=current[key]
            elif isinstance(current,list) and key.isdigit(): current=current[int(key)]
            else: raise ValueError(f"Path not found at '{key}'.")
            if index is not None:
                if not isinstance(current,list) or int(index)>=len(current): raise ValueError("Array index is out of range.")
                current=current[int(index)]
        return {"value":current}
    if tool_id in ("csv_summary", "html_table"):
        rows=list(csv.reader(io.StringIO(text)))
        if not rows: raise ValueError("Enter CSV data first.")
        if tool_id == "csv_summary": return {"rows_excluding_header":max(0,len(rows)-1),"columns":rows[0],"preview":rows[:6]}
        headers=rows[0]
        parts=["<table><thead><tr>"+"".join(f"<th>{html.escape(cell)}</th>" for cell in headers)+"</tr></thead><tbody>"]
        for row in rows[1:]: parts.append("<tr>"+"".join(f"<td>{html.escape(cell)}</td>" for cell in row)+"</tr>")
        parts.append("</tbody></table>")
        return {"html":"".join(parts)}
    if tool_id == "base64_encode": return {"base64":base64.b64encode(text.encode("utf-8")).decode("ascii")}
    if tool_id == "base64_decode":
        try: decoded=base64.b64decode(text,validate=True).decode("utf-8")
        except Exception as exc: raise ValueError("Enter valid Base64 containing UTF-8 text.") from exc
        return {"text":decoded}
    if tool_id == "url_encode": return {"encoded":quote(text,safe="")}
    if tool_id == "url_decode": return {"decoded":unquote(text)}
    if tool_id == "calculate": return {"result":_safe_math(str(args.get("expression", "")))}
    if tool_id == "percentage": return {"result":_number(args.get("value",0),"Value")*_number(args.get("percent",0),"Percent")/100}
    if tool_id == "percentage_change":
        old,new=_number(args.get("old",0),"Original value"),_number(args.get("new",0),"New value")
        if old == 0: raise ValueError("Original value cannot be zero for percentage change.")
        return {"change_percent":round((new-old)/abs(old)*100,4),"difference":new-old}
    if tool_id == "average":
        raw=args.get("values", "")
        vals=raw if isinstance(raw,list) else [x.strip() for x in str(raw).split(",") if x.strip()]
        values=[_number(v) for v in vals]
        if not values: raise ValueError("Enter numbers separated by commas.")
        return {"average":sum(values)/len(values),"count":len(values)}
    if tool_id == "ratio":
        raw_a,raw_b=_number(args.get("a",0)),_number(args.get("b",0))
        if not raw_a.is_integer() or not raw_b.is_integer(): raise ValueError("Ratio values must be whole numbers.")
        a,b=int(raw_a),int(raw_b)
        if a < 0 or b < 0 or (a == 0 and b == 0): raise ValueError("Enter non-negative values; they cannot both be zero.")
        g=math.gcd(a,b)
        return {"simplified":f"{a//g}:{b//g}","divisor":g}
    if tool_id == "circle":
        r=_number(args.get("radius",0),"Radius")
        if r < 0: raise ValueError("Radius cannot be negative.")
        return {"area":math.pi*r*r,"circumference":2*math.pi*r}
    if tool_id == "triangle_area": return {"area":_number(args.get("base",0),"Base")*_number(args.get("height",0),"Height")/2}
    if tool_id == "pythagorean": return {"hypotenuse":math.hypot(_number(args.get("a",0)),_number(args.get("b",0)))}
    if tool_id == "factorial":
        raw_n=_number(args.get("n",0),"Number")
        if not raw_n.is_integer(): raise ValueError("Enter a whole number from 0 to 170.")
        n=int(raw_n)
        if n < 0 or n > 170: raise ValueError("Enter a whole number from 0 to 170.")
        return {"factorial":math.factorial(n)}
    if tool_id == "today":
        now=dt.datetime.now().astimezone()
        return {"local_datetime":now.isoformat(timespec="seconds"),"weekday":now.strftime("%A"),"timezone":str(now.tzinfo)}
    if tool_id == "add_days":
        d=dt.date.fromisoformat(str(args.get("date"))); return {"date":(d+dt.timedelta(days=int(_number(args.get("days",0))))).isoformat()}
    if tool_id == "days_between":
        a,b=dt.date.fromisoformat(str(args.get("start"))),dt.date.fromisoformat(str(args.get("end")))
        return {"days":(b-a).days,"absolute_days":abs((b-a).days)}
    if tool_id == "weekday": return {"weekday":dt.date.fromisoformat(str(args.get("date"))).strftime("%A")}
    if tool_id == "leap_year":
        y=int(_number(args.get("year",dt.date.today().year)))
        return {"year":y,"is_leap_year":y%4==0 and (y%100!=0 or y%400==0)}
    if tool_id == "age":
        born=dt.date.fromisoformat(str(args.get("birth_date"))); today=dt.date.today()
        if born > today: raise ValueError("Date of birth cannot be in the future.")
        years=today.year-born.year; months=today.month-born.month; days=today.day-born.day
        if days < 0:
            prev_month=today.month-1 or 12; prev_year=today.year if today.month>1 else today.year-1
            days += (dt.date(today.year,today.month,1)-dt.date(prev_year,prev_month,1)).days
            months -= 1
        if months < 0: months += 12; years -= 1
        return {"years":years,"months":months,"days":days}
    if tool_id == "business_days":
        start,end=dt.date.fromisoformat(str(args.get("start"))),dt.date.fromisoformat(str(args.get("end")))
        if end < start: start,end=end,start
        if (end-start).days>36600: raise ValueError("Date range is limited to 100 years.")
        count=0; cur=start
        while cur <= end:
            if cur.weekday()<5: count+=1
            cur += dt.timedelta(days=1)
        return {"weekdays_inclusive":count}
    if tool_id == "next_weekday":
        target=int(_number(args.get("weekday",1)))
        if target<1 or target>7: raise ValueError("Weekday must be from 1 (Monday) to 7 (Sunday).")
        today=dt.date.today(); delta=(target-1-today.weekday())%7
        if delta==0: delta=7
        result=today+dt.timedelta(days=delta)
        return {"date":result.isoformat(),"weekday":result.strftime("%A")}
    if tool_id == "hex_rgb":
        h=str(args.get("hex", "#000000")).strip().lstrip("#")
        if len(h)==3: h="".join(ch*2 for ch in h)
        if not re.fullmatch(r"[0-9a-fA-F]{6}",h): raise ValueError("Enter a 3- or 6-digit HEX colour.")
        return {"r":int(h[0:2],16),"g":int(h[2:4],16),"b":int(h[4:6],16)}
    if tool_id == "rgb_hex":
        vals=[int(_number(args.get(k,0),k.upper())) for k in ("r","g","b")]
        if any(v<0 or v>255 for v in vals): raise ValueError("RGB values must be from 0 to 255.")
        return {"hex":"#"+"".join(f"{v:02X}" for v in vals)}
    if tool_id == "uuid": return {"uuid":str(uuid.uuid4())}
    if tool_id == "random_int":
        raw_low,raw_high=_number(args.get("minimum",1)),_number(args.get("maximum",100))
        if not raw_low.is_integer() or not raw_high.is_integer(): raise ValueError("Minimum and maximum must be whole numbers.")
        low,high=int(raw_low),int(raw_high)
        if high<low: raise ValueError("Maximum must be greater than or equal to minimum.")
        if high-low>10**12: raise ValueError("Range is too large.")
        return {"value":random.randint(low,high)}
    if tool_id == "url_info":
        raw=str(args.get("url", "")).strip(); parsed=urlparse(raw)
        if parsed.scheme not in ("http","https") or not parsed.netloc: raise ValueError("Enter a full http:// or https:// URL.")
        return {"scheme":parsed.scheme,"host":parsed.netloc,"path":parsed.path or "/","query":parsed.query,"fragment":parsed.fragment}

    if tool_id in ("web_search", "web_search_news"):
        return _web_search(str(args.get("query", "")),cfg,"news" if tool_id=="web_search_news" else "general",int(_number(args.get("max_results",5))))
    if tool_id in ("web_open_url", "web_extract_links", "web_page_title", "url_status", "http_headers"):
        page=_fetch_public_url(str(args.get("url", "")))
        parser=_PublicPageParser()
        if "html" in page["content_type"] or "<html" in page["body"].lower()[:1000]: parser.feed(page["body"])
        if tool_id=="url_status": return {"url":page["url"],"status":page["status"],"content_type":page["content_type"]}
        if tool_id=="http_headers":
            # Fetch a small public response once more to expose only response headers.
            r=requests.get(page["url"],headers={"User-Agent":"JARVIS-Android-Assistant/2.0"},timeout=(8,18),allow_redirects=False,stream=True)
            out={k:v for k,v in r.headers.items()}; r.close()
            return {"url":page["url"],"headers":out}
        if tool_id=="web_page_title": return {"url":page["url"],"title":" ".join(parser.title_parts)[:300] or "No HTML title found."}
        if tool_id=="web_extract_links":
            links=[]
            for href,label in parser.links[:100]:
                target=urljoin(page["url"],href)
                if urlparse(target).scheme in ("http","https"): links.append({"text":label[:180],"url":target})
            return {"url":page["url"],"links":links,"count":len(links)}
        return {"url":page["url"],"status":page["status"],"title":" ".join(parser.title_parts)[:300],"text":" ".join(parser.text_parts)[:10000]}
    if tool_id=="internet_status":
        started=time.time()
        try:
            r=requests.get("https://www.google.com/generate_204",timeout=(5,10),allow_redirects=True)
            return {"online":r.status_code in (200,204),"http_status":r.status_code,"latency_ms":round((time.time()-started)*1000)}
        except requests.RequestException as exc: return {"online":False,"error":exc.__class__.__name__}
    if tool_id=="dns_lookup":
        host=str(args.get("hostname", "")).strip().strip(".")
        if not host or len(host)>253 or not re.fullmatch(r"[A-Za-z0-9.-]+",host): raise ValueError("Enter a valid public hostname.")
        if host.lower()=="localhost" or host.lower().endswith((".local",".internal")): raise ValueError("Local hostnames are blocked.")
        try: infos=socket.getaddrinfo(host,None)
        except OSError as exc: raise ValueError("DNS lookup failed: "+str(exc)[:160]) from exc
        addresses=sorted({item[4][0] for item in infos})
        if any(not ipaddress.ip_address(a).is_global for a in addresses): raise ValueError("Private or reserved DNS results are blocked.")
        return {"hostname":host,"addresses":addresses}
    if tool_id=="public_ip":
        try:
            r=requests.get("https://api.ipify.org",timeout=(6,12)); r.raise_for_status(); ip=r.text.strip()
            if not ipaddress.ip_address(ip).is_global: raise ValueError("External service did not return a public IP.")
            return {"public_ip":ip}
        except requests.RequestException as exc: raise ValueError("Public IP lookup failed: "+exc.__class__.__name__) from exc
    if tool_id in ("regex_test","regex_extract","regex_replace"):
        source=str(args.get("text", ""))[:50000]; pattern=str(args.get("pattern", ""))
        if len(pattern)>300: raise ValueError("Regex pattern is limited to 300 characters.")
