# ------------------------------ Speech engines ------------------------------

class SpeechError(Exception):
    pass


def _clean_speech_text(value: str) -> str:
    """Turn assistant Markdown into natural text without changing its wording."""
    text = html.unescape(str(value or ""))
    # Keep link labels, discard code fences and raw URLs that are poor TTS inputs.
    text = re.sub(r"```[\s\S]*?```", " ", text)
    text = re.sub(r"`([^`]+)`", r"\1", text)
    text = re.sub(r"!?\[([^\]]+)\]\([^)]*\)", r"\1", text)
    text = re.sub(r"https?://\S+|www\.\S+", " ", text)
    # Speak assistant names as names, not as a sequence of separated letters.
    text = re.sub(r"\bJ\.\s*A\.\s*R\.\s*V\.\s*I\.\s*S\.?", "Jarvis", text, flags=re.I)
    text = re.sub(r"\bF\.\s*R\.\s*I\.\s*D\.\s*A\.\s*Y\.?", "Friday", text, flags=re.I)
    text = re.sub(r"\bE\.\s*D\.\s*I\.\s*T\.\s*H\.?", "Edith", text, flags=re.I)
    # Remove Markdown decoration while preserving the readable words.
    text = re.sub(r"^\s{0,3}#{1,6}\s*", "", text, flags=re.M)
    text = re.sub(r"\*\*(.*?)\*\*|__(.*?)__", lambda m: m.group(1) or m.group(2), text)
    text = re.sub(r"(?<!\*)\*(?!\*)(.*?)\*(?!\*)|(?<!_)_(?!_)(.*?)_(?!_)", lambda m: m.group(1) or m.group(2), text)
    text = re.sub(r"^[ \t]*[-*+]\s+", "", text, flags=re.M)
    text = re.sub(r"^[ \t]*\d+[.)]\s+", "", text, flags=re.M)
    text = text.replace("\u2022", " ").replace("\u2013", ", ").replace("\u2014", ", ")
    # Strip emoji/symbol ranges but keep letters, punctuation, and numbers.
    text = re.sub(r"[\U0001F000-\U0001FAFF\U00002600-\U000027BF]", " ", text)
    text = re.sub(r"[\t\r ]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


def _persona_voice(cfg: dict, provider: str) -> tuple[str, str]:
    persona=str(cfg.get("persona", "J.A.R.V.I.S."))
    profile=PERSONA_VOICES.get(persona, PERSONA_VOICES["J.A.R.V.I.S."])
    field={"gemini":"gemini_voice","azure":"azure_voice","edge":"edge_voice"}[provider]
    voice=str(cfg.get(field, "")).strip() or profile[provider]
    return voice, profile["style"]


def _gemini_tts(text: str, cfg: dict) -> tuple[bytes, str]:
    key=str(cfg.get("gemini_key", "")).strip()
    if not key: raise SpeechError("Gemini key is not configured; skipping Gemini.")
    model=str(cfg.get("gemini_tts_model", DEFAULT_GEMINI_TTS_MODEL)).strip()
    if model not in ("gemini-3.6-flash-lite-tts", "gemini-3.6-flash-tts"):
        raise SpeechError("Choose a supported Gemini 3.8 TTS model.")
    voice,style=_persona_voice(cfg,"gemini")
    # Current Gemini 3.8 TTS Interactions API. Style instructions are metadata,
    # not prepended to the transcript, so they are not spoken aloud.
    payload={
        "model":model,
        "input":[{"type":"user_input","content":[{"type":"text","text":text,
            "annotations":[{"type":"speech_metadata","style":style}]}]}],
        "response_format":{"type":"audio"},
        "generation_config":{"speech_config":[{"voice":voice}]}
    }
    headers={"x-goog-api-key":key,"Content-Type":"application/json"}
    try:
        r=requests.post("https://generativelanguage.googleapis.com/v1beta/interactions",headers=headers,json=payload,timeout=(10,120))
        if r.status_code>=400:
            try: detail=r.json().get("error",{}).get("message",f"HTTP {r.status_code}")
            except Exception: detail=f"HTTP {r.status_code}"
            raise SpeechError(f"Gemini TTS: {str(detail)[:220]}")
        data=r.json()
        audio_obj=data.get("output_audio") or {}
        encoded=audio_obj.get("data") if isinstance(audio_obj,dict) else None
        if not encoded:
            for step in data.get("steps",[]):
                out=step.get("content") or []
                for item in out:
                    if item.get("type")=="audio" and item.get("data"):
                        encoded=item["data"]; break
                if encoded: break
        if encoded:
            audio=base64.b64decode(encoded)
            if audio: return audio,"audio/wav"
        raise SpeechError("Gemini completed without returning audio data.")
    except requests.RequestException as exc:
        raise SpeechError(f"Gemini network error: {exc.__class__.__name__}") from exc


def _azure_tts(text: str, cfg: dict) -> tuple[bytes, str]:
    key=str(cfg.get("azure_key", "")).strip()
    region=str(cfg.get("azure_region", "southeastasia")).strip().lower()
    voice,_=_persona_voice(cfg,"azure")
    if not key: raise SpeechError("Azure key is not configured; skipping Azure.")
    if not re.fullmatch(r"[a-z0-9-]{2,40}",region): raise SpeechError("Azure region is invalid.")
    if not re.fullmatch(r"en-GB-[A-Za-z]+Neural",voice): raise SpeechError("Choose a British English Azure voice.")
    escaped=html.escape(text,quote=True)
    ssml=(f'<speak version="1.0" xmlns="http://www.w3.org/2001/10/synthesis" '
          f'xml:lang="en-GB"><voice name="{voice}"><prosody rate="-4%" pitch="-2%">'
          f'{escaped}</prosody></voice></speak>')
    url=f"https://{region}.tts.speech.microsoft.com/cognitiveservices/v1"
    headers={"Ocp-Apim-Subscription-Key":key,"Content-Type":"application/ssml+xml",
             "X-Microsoft-OutputFormat":"audio-24khz-48kbitrate-mono-mp3","User-Agent":"JARVIS-Android-Edition"}
    try:
        r=requests.post(url,data=ssml.encode("utf-8"),headers=headers,timeout=(10,60))
        if r.status_code>=400: raise SpeechError(f"Azure Speech: HTTP {r.status_code} — {r.text[:160]}")
        if not r.content: raise SpeechError("Azure returned an empty audio file.")
        return r.content,"audio/mpeg"
    except requests.RequestException as exc:
        raise SpeechError(f"Azure network error: {exc.__class__.__name__}") from exc


def _edge_tts(text: str, cfg: dict) -> tuple[bytes, str]:
    try: import edge_tts
    except ImportError as exc: raise SpeechError("Edge TTS package is not installed. Run: pip install edge-tts") from exc
    voice,_=_persona_voice(cfg,"edge")
    rate=str(cfg.get("edge_rate", "-4%"))
    if not re.fullmatch(r"[+-](?:0|[1-9]\d?)%",rate): rate="-4%"
    async def make_file(path: str):
        await edge_tts.Communicate(text=text,voice=voice,rate=rate,pitch="-2Hz").save(path)
    fd,path=tempfile.mkstemp(suffix=".mp3"); os.close(fd)
    try:
        asyncio.run(make_file(path))
        audio=Path(path).read_bytes()
        if not audio: raise SpeechError("Edge TTS returned an empty audio file.")
        return audio,"audio/mpeg"
    except SpeechError: raise
    except Exception as exc: raise SpeechError(f"Edge TTS failed: {exc.__class__.__name__}") from exc
    finally:
        try: os.unlink(path)
        except OSError: pass


SPEECH_PROVIDERS: dict[str, Callable[[str,dict],tuple[bytes,str]]] = {"gemini":_gemini_tts,"azure":_azure_tts,"edge":_edge_tts}


def _provider_order(preferred: str, fallback: bool) -> list[str]:
    # British neural voices first for dependable en-GB pronunciation. Gemini
    # remains available as an explicit option and as the final automatic fallback.
    order=["edge","azure","gemini"]
    if preferred == "auto":
        return order if fallback else ["gemini"]
    if preferred in SPEECH_PROVIDERS:
        order.remove(preferred)
        order.insert(0,preferred)
    return order if fallback else [order[0]]

