def _call_chat_provider(provider: str, messages: list, cfg: dict, image: dict | None = None) -> tuple[str, list]:
    provider = str(provider or "").lower()
    if provider == "ollama":
        return _chat_ollama(messages, cfg, image=image), []
    if provider == "gemini":
        answer, sources = _chat_gemini(messages, cfg, image=image, use_search=False)
        return answer, sources
    if provider == "openrouter":
        outgoing = [dict(m) for m in messages]
        if image and outgoing:
            last = outgoing[-1]
            content = str(last.get("content", ""))
            last["content"] = [
                {"type":"text", "text":content},
                {"type":"image_url", "image_url":{"url":"data:"+image["mime_type"]+";base64,"+image["data"]}}
            ]
        model_override = str(cfg.get("openrouter_vision_model", "")).strip() if image else ""
        return _chat_openrouter(outgoing, cfg, model_override=model_override), []
    raise ValueError("Unsupported AI provider.")


def _offline_core_reply(user_text: str, has_image: bool = False) -> str | None:
    """Small deterministic fallback; it is not a replacement for a language model."""
    if has_image:
        return "The AI providers and local vision model are unavailable, so I cannot inspect this image offline. The local utility tools are still available."
    text = str(user_text or "").strip()
    low = text.lower()
    now = dt.datetime.now().astimezone()
    if re.search(r"\b(what time|current time|time is it)\b", low):
        return "Local device-server time: " + now.strftime("%A, %d %B %Y at %I:%M %p %Z") + ". I am using the offline local core."
    if re.search(r"\b(what date|today's date|current date|date today)\b", low):
        return "Local date: " + now.strftime("%A, %d %B %Y") + ". I am using the offline local core."
    match = re.search(r"(?:calculate|what is|solve)\s+(.+?)[?!.]*$", text, re.I)
    candidate = match.group(1).strip() if match else ""
    if candidate and len(candidate) < 120:
        try:
            value = _safe_math(candidate)
            return f"The result is {value}. This answer was calculated by JARVIS's offline math core."
        except Exception:
            pass
    if low in ("hi", "hello", "hey", "hello jarvis", "jarvis"):
        return "Hello. The local core is online. Connect an Ollama model or a cloud provider for full language understanding."
    return None


def _ask_provider_with_fallback(provider: str, messages: list, cfg: dict, image: dict | None = None) -> tuple[str, str, list, list]:
    attempts = []
    try:
        answer, sources = _call_chat_provider(provider, messages, cfg, image=image)
        return answer, provider, sources, attempts
    except Exception as primary_error:
        attempts.append(f"{provider}: {str(primary_error)[:220]}")
        if provider != "ollama" and bool(cfg.get("ollama_fallback", False)):
            try:
                answer, sources = _call_chat_provider("ollama", messages, cfg, image=image)
                return answer, "ollama-local-fallback", sources, attempts
            except Exception as local_error:
                attempts.append(f"ollama fallback: {str(local_error)[:220]}")
        local = _offline_core_reply(str(messages[-1].get("content", "")) if messages else "", bool(image))
        if local:
            return local, "offline-core", [], attempts
        details = " | ".join(attempts)
        raise ValueError("Primary AI provider failed" + ("; local Ollama fallback also failed" if len(attempts)>1 else "") + ". " + details)


def _chat_openrouter(messages: list, cfg: dict, model_override: str = "") -> str:
    key=str(cfg.get("openrouter_key", "")).strip()
    if not key: raise ValueError("OpenRouter API key is missing. Open Voice & AI settings and enter it.")
    model=str(model_override or cfg.get("chat_model", DEFAULT_CHAT_MODEL)).strip() or DEFAULT_CHAT_MODEL
    if len(model)>150: raise ValueError("Model ID is too long.")
    headers={"Authorization":f"Bearer {key}","Content-Type":"application/json","HTTP-Referer":"http://127.0.0.1:8765","X-Title":"JARVIS Android Edition"}
    try: max_tokens=min(max(int(cfg.get("max_tokens",1024)),256),4096)
    except (TypeError,ValueError): max_tokens=1024
    payload={"model":model,"messages":messages,"max_tokens":max_tokens,"temperature":0.7}
    try: r=requests.post("https://openrouter.ai/api/v1/chat/completions",headers=headers,json=payload,timeout=(12,120))
    except requests.RequestException as exc: raise ValueError(f"OpenRouter connection error: {exc.__class__.__name__}. Check internet and try again.") from exc
    if r.status_code>=400:
        try: error=r.json().get("error",{}).get("message",f"HTTP {r.status_code}")
        except Exception: error=f"HTTP {r.status_code}: {r.text[:150]}"
        if "image" in str(error).lower() or "vision" in str(error).lower():
            raise ValueError(f"The selected OpenRouter model may not support images. Set a vision-capable model in Vision model settings. Provider says: {str(error)[:220]}")
        raise ValueError(f"OpenRouter: {str(error)[:300]}")
    try: data=r.json()
    except ValueError as exc: raise ValueError("OpenRouter returned invalid JSON.") from exc
    content=data.get("choices",[{}])[0].get("message",{}).get("content","")
    if isinstance(content,list): content="\n".join(str(x.get("text", "")) for x in content if isinstance(x,dict))
    return str(content).strip() or "I received an empty response. Please try again."


def _chat_ollama(messages: list, cfg: dict, image: dict | None = None) -> str:
    base=str(cfg.get("ollama_url", "http://127.0.0.1:11434")).strip().rstrip("/")
    parsed=urlparse(base)
    if parsed.scheme not in ("http","https") or not parsed.netloc: raise ValueError("Ollama URL must start with http:// or https://.")
    model=str((cfg.get("ollama_vision_model") if image else "") or cfg.get("ollama_model", "llama3.2")).strip() or "llama3.2"
    is_openai=base.endswith("/v1")
    if base.endswith("/api"): url=base+"/chat"
    elif is_openai: url=base+"/chat/completions"
    else: url=base+"/api/chat"
    outgoing=[dict(m) for m in messages]
    if image and outgoing:
        last=outgoing[-1]
        if is_openai:
            content=str(last.get("content", ""))
            last["content"]=[{"type":"text","text":content},{"type":"image_url","image_url":{"url":"data:"+image["mime_type"]+";base64,"+image["data"]}}]
        else:
            last["images"]=[image["data"]]
    payload={"model":model,"messages":outgoing,"stream":False}
    try: r=requests.post(url,json=payload,timeout=(12,180))
    except requests.RequestException as exc: raise ValueError(f"Ollama connection error: {exc.__class__.__name__}. Check that the Ollama server is reachable.") from exc
    if r.status_code>=400:
        detail=r.text[:220]
        if image and ("vision" in detail.lower() or "image" in detail.lower()):
            raise ValueError("The selected Ollama model may not support images. Use a vision model such as a locally installed vision-capable model and set it in Ollama vision model.")
        raise ValueError(f"Ollama: HTTP {r.status_code} — {detail}")
    data=r.json()
    content=(data.get("choices",[{}])[0].get("message",{}).get("content","") if is_openai else data.get("message",{}).get("content",""))
    return str(content).strip() or "I received an empty response."


def _chat_gemini(messages: list, cfg: dict, image: dict | None = None, use_search: bool = False) -> tuple[str,list]:
    key=str(cfg.get("gemini_key", "")).strip()
    if not key: raise ValueError("Gemini API key is missing. Enter it in Voice & AI settings.")
    model=str(cfg.get("gemini_chat_model", "gemini-3.8-flash")).strip() or "gemini-3.8-flash"
    model=re.sub(r"[^A-Za-z0-9._-]", "", model)
    if not model: raise ValueError("Enter a valid Gemini chat model name.")
    system=messages[0].get("content", "") if messages and messages[0].get("role")=="system" else "You are JARVIS, a helpful assistant."
    contents=[]
    for msg in messages[1:] if messages and messages[0].get("role")=="system" else messages:
        role="model" if msg.get("role")=="assistant" else "user"
        text=str(msg.get("content", ""))
        parts=[{"text":text}]
        if image and role=="user" and msg is messages[-1]:
            parts.append({"inlineData":{"mimeType":image["mime_type"],"data":image["data"]}})
        contents.append({"role":role,"parts":parts})
    if not contents: raise ValueError("Send a message first.")
    try: max_tokens=min(max(int(cfg.get("max_tokens",1024)),256),4096)
    except (TypeError,ValueError): max_tokens=1024
    payload={"systemInstruction":{"parts":[{"text":system}]},"contents":contents,"generationConfig":{"maxOutputTokens":max_tokens,"temperature":0.7}}
    if use_search: payload["tools"]=[{"google_search":{}}]
    try: response=requests.post(f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent",headers={"x-goog-api-key":key,"Content-Type":"application/json"},json=payload,timeout=(12,150))
    except requests.RequestException as exc: raise ValueError(f"Gemini connection error: {exc.__class__.__name__}.") from exc
    if response.status_code>=400:
        try: detail=response.json().get("error",{}).get("message",f"HTTP {response.status_code}")
        except Exception: detail=f"HTTP {response.status_code}"
        if image and ("image" in str(detail).lower() or "modality" in str(detail).lower()):
            raise ValueError("Gemini rejected the image. Check that your selected model accepts image input and that the image is JPG, PNG, WebP or GIF.")
        raise ValueError(f"Gemini: {str(detail)[:260]}")
    data=response.json(); candidates=data.get("candidates",[])
    if not candidates: raise ValueError("Gemini returned no answer. The prompt may have been blocked or the model is unavailable.")
    parts=candidates[0].get("content",{}).get("parts",[])
    answer="\n".join(str(part.get("text","")) for part in parts if isinstance(part,dict) and part.get("text"))
    grounding=candidates[0].get("groundingMetadata",{}) or {}
    sources=[]
    for chunk in grounding.get("groundingChunks",[]):
        web=chunk.get("web",{}) if isinstance(chunk,dict) else {}
        uri=web.get("uri")
        if uri and str(uri).startswith("https://"): sources.append({"title":str(web.get("title") or uri)[:200],"url":str(uri)})
    return answer.strip() or "Gemini returned an empty response.", _dedupe_sources(sources)


def _dedupe_sources(sources: list[dict]) -> list[dict]:
    out=[]; seen=set()
    for item in sources:
        url=str(item.get("url", ""))
        if url.startswith(("https://","http://")) and url not in seen:
            seen.add(url); out.append({"title":str(item.get("title") or url)[:200],"url":url})
    return out[:10]

