def _serve_index():
    # Only serve the page beside this script. Pydroid sometimes runs an editor
    # buffer from a temp directory; in that case use the matching embedded UI
    # rather than accidentally serving an unrelated older index.html in CWD.
    candidate=APP_DIR/"index.html"
    try:
        if candidate.is_file(): return send_file(candidate,mimetype="text/html")
    except OSError:
        pass
    try:
        page=gzip.decompress(base64.b64decode(EMBEDDED_INDEX_GZIP_B64))
        return Response(page,mimetype="text/html; charset=utf-8")
    except Exception:
        app.logger.exception("Unable to load embedded JARVIS interface")
        return Response("JARVIS could not load its embedded interface. Re-extract the project ZIP.",status=500,mimetype="text/plain; charset=utf-8")


@app.get("/")
@app.get("/index.html")
def home(): return _serve_index()


