    return {"ok":True,"status":"online","ready":True,"version":VERSION,"uptime_seconds":uptime,
            "tool_count":len(TOOL_SPECS)+custom_count+expansion_count,"custom_tool_count":custom_count,"expansion_tool_count":expansion_count,"conversion_tool_count":len(TOOL_CONVERSIONS),"local_tool_count":len(TOOL_SPECS)-len(TOOL_CONVERSIONS),"categories":len(set(TOOL_CATEGORIES[1:]) | expansion_categories | ({"custom_extensions"} if custom_count else set())),"speech_providers":["edge","azure","gemini"],"speech_auto_order":["edge","azure","gemini"],"personas":list(PERSONAS),"agent_presets":len(AGENT_PRESETS),"local_fallback":"ollama","persistent_self_upgrade":True,"image_engines":["auto","gemini","local_sd","offline_svg"],"svg_builder":True,"expansion_version":"2.4.0","memory_enabled":True,"mcp_enabled":True,"coding_workspace":True,"automation_studio":True,"live_vision":True,"ecosystem_enabled":bool(globals().get("ECOSYSTEM_MANAGER"))}


