@app.post("/api/tts")
def tts():
    data=request.get_json(silent=True) or {}
    original_text=str(data.get("text", ""))
    text=_clean_speech_text(original_text)
    if not text: return jsonify({"error":"There is no readable text to speak after removing formatting."}),400
    if len(text)>MAX_TEXT_CHARS: return jsonify({"error":f"Speech is limited to {MAX_TEXT_CHARS} readable characters."}),400
    cfg=data.get("settings",{})
    if not isinstance(cfg,dict): cfg={}
    cfg["persona"]=str(data.get("persona",cfg.get("persona","J.A.R.V.I.S.")))
    preferred=str(cfg.get("speech_provider","auto")).lower()
    fallback=bool(cfg.get("speech_fallback",True))
    attempts=[]
    for provider in _provider_order(preferred,fallback):
        try:
            audio,mime=SPEECH_PROVIDERS[provider](text,cfg)
            if not isinstance(audio, (bytes, bytearray)) or len(audio) < 256:
                raise SpeechError("Provider returned an incomplete audio file.")
            if provider == "gemini" and not (bytes(audio).startswith(b"RIFF") and bytes(audio)[8:12] == b"WAVE"):
                raise SpeechError("Gemini returned audio without a valid WAV header; trying the next British voice provider.")
            if provider in ("azure", "edge") and not (bytes(audio).startswith(b"ID3") or (len(audio) > 2 and bytes(audio)[0] == 0xFF and (bytes(audio)[1] & 0xE0) == 0xE0)):
                raise SpeechError("Provider returned an invalid MP3 file; trying the next voice provider.")
            response=Response(bytes(audio),mimetype=mime)
            response.headers["X-JARVIS-TTS-Provider"]=provider
            response.headers["X-JARVIS-TTS-Voice"]=_persona_voice(cfg,provider)[0]
            response.headers["X-JARVIS-TTS-Attempts"]=";".join(attempts+[provider])
            response.headers["Cache-Control"]="no-store"
            return response
        except Exception as exc:
            attempts.append(f"{provider}: {str(exc)[:180]}")
    return jsonify({"error":"No speech provider completed the request.","attempts":attempts,"browser_fallback_available":True}),503


