@app.post("/api/agents/run")
def agents_run():
    data=request.get_json(silent=True) or {}
    cfg=data.get("settings",{})
    if not isinstance(cfg,dict): cfg={}
    task=str(data.get("task", "")).strip()
    agents=data.get("agents", [])
    if not task: return jsonify({"ok":False,"error":"Enter a task for the agents."}),400
    if len(task)>7000: return jsonify({"ok":False,"error":"Agent task is limited to 7,000 characters."}),400
    if not isinstance(agents,list) or not agents: return jsonify({"ok":False,"error":"Select at least one agent."}),400
    if len(agents)>4: return jsonify({"ok":False,"error":"Choose up to four agents per run. You can save up to 20 agent profiles."}),400
    provider=str(cfg.get("chat_provider","openrouter")).lower()
    if provider not in ("openrouter","ollama","gemini"): return jsonify({"ok":False,"error":"Choose a valid AI provider in settings."}),400
    results=[]
    for item in agents:
        if not isinstance(item,dict): continue
        name=re.sub(r"[^\w .'-]", "", str(item.get("name","Agent")))[:40] or "Agent"
        role=str(item.get("role","Specialist"))[:100]
        instructions=str(item.get("prompt", ""))[:1400]
        system=("You are a specialist subagent inside JARVIS. Your name is "+name+". Role: "+role+".\n"+instructions+"\nReturn a useful independent contribution. Be accurate, concise, and honest about uncertainty. Do not claim you used tools or searched the web unless the request context shows that. Avoid unsafe instructions.")
        try:
            answer, used, _, attempts = _ask_provider_with_fallback(provider,[{"role":"system","content":system},{"role":"user","content":task}],cfg,None)
            results.append({"name":name,"role":role,"provider":used,"ok":True,"answer":answer,"fallback_attempts":attempts})
        except Exception as exc:
            results.append({"name":name,"role":role,"provider":provider,"ok":False,"error":str(exc)[:400]})
    return jsonify({"ok":bool(results) and any(x.get("ok") for x in results),"results":results,"count":len(results)})


