def _make_agent_catalog():
    rows = []
    for group, names, keys in _AGENT_GROUPS:
        for index, (name, keywords) in enumerate(zip(names, keys)):
            role = f"{group} specialist · {name}"
            rows.append({
                "id":re.sub(r"[^a-z0-9]+", "_", group.lower()).strip("_") + "_" + str(index+1),
                "name":name, "role":role,
                "prompt":f"Act as the {name} for JARVIS. Focus on {keywords}. Give an independent, evidence-aware contribution. State assumptions and limitations; do not claim unavailable tools or fabricated research.",
                "keywords":keywords, "custom":False, "provider_id":"auto", "model":"auto"
            })
    return rows


AGENT_PRESETS = _make_agent_catalog()


def _agent_relevance(agent, task):
    task_words = set(re.findall(r"[a-z0-9]{3,}", str(task).lower()))
    searchable = " ".join([str(agent.get("name", "")), str(agent.get("role", "")), str(agent.get("keywords", "")), str(agent.get("prompt", ""))]).lower()
    words = set(re.findall(r"[a-z0-9]{3,}", searchable))
    score = len(task_words & words)
    task_low = str(task).lower()
    groups = str(agent.get("role", "")).lower()
    for hint, add in [("image",4),("photo",3),("picture",3),("code",4),("python",4),("bug",4),("web",4),("search",3),("calculate",4),("math",4),("school",4),("homework",4),("design",3),("write",3),("story",4),("game",4),("android",4),("api",4),("security",4),("privacy",3),("data",3),("spreadsheet",4),("plan",3),("schedule",3)]:
        if hint in task_low and hint in searchable:
            score += add
    if "quality" in groups and any(x in task_low for x in ("review", "check", "test", "fix")):
        score += 4
    return score


def _gateway_provider_by_id(provider_id, cfg=None, model="auto"):
    candidates = _gateway_candidates(cfg or {}, model=model, provider_id=provider_id)
    return candidates[0] if candidates else None


def _agent_execute(item, task, cfg):
    name = re.sub(r"[^\w .'-]", "", str(item.get("name", "Agent")))[:50] or "Agent"
    role = str(item.get("role", "Specialist"))[:120]
    instructions = str(item.get("prompt", ""))[:1800]
    system = "You are a specialist subagent inside JARVIS. Your name is " + name + ". Role: " + role + ".\n" + instructions + "\nReturn a useful independent contribution. Be accurate and honest about uncertainty. Do not fabricate web sources or claim tools were used unless included in context. Avoid unsafe instructions."
    provider_id = str(item.get("provider_id", "auto") or "auto")
    model = str(item.get("model", "auto") or "auto")
    messages = [{"role":"system", "content":system}, {"role":"user", "content":task[:7000]}]
    if provider_id == "auto":
        answer, used, src, _, _, attempts, usage = _router_agentic_chat(messages, cfg, tools_enabled=False, selected_model=model)
    else:
        answer, used, src, _, _, attempts, usage = _router_agentic_chat(messages, cfg, tools_enabled=False, selected_model=model, provider_id=provider_id)
    return {"name":name,"role":role,"provider":used,"ok":True,"answer":answer,"sources":src,"fallback_attempts":attempts,"usage":usage}


def _gateway_auth_ok():
    auth = str(request.headers.get("Authorization", ""))
    token = auth[7:].strip() if auth.lower().startswith("bearer ") else ""
    expected = str(_gateway_read_state().get("token", ""))
    return bool(token and expected and hmac.compare_digest(token, expected))


