# v2.4.0 ecosystem: marketplace, visual workflows, snapshots, knowledge vault and device pairing.
ECOSYSTEM_MANAGER = None
ECOSYSTEM_SOURCE_GZIP_B64 = r""""""

def _load_ecosystem_register():
    """Load the ecosystem from the project folder or its embedded fallback.

    Pydroid can execute an editor buffer from a temporary filename; embedding
    the module ensures the same features remain available in that case.
    """
    import types
    source_path = APP_DIR / "jarvis_ecosystem.py"
    raw = None
    try:
        if source_path.is_file():
            raw = source_path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        raw = None
    if raw is None:
        raw = gzip.decompress(base64.b64decode(ECOSYSTEM_SOURCE_GZIP_B64)).decode("utf-8")
    module = types.ModuleType("jarvis_embedded_ecosystem")
    module.__file__ = str(source_path) if source_path.is_file() else "<embedded:jarvis_ecosystem.py>"
    exec(compile(raw, module.__file__, "exec"), module.__dict__)
    return module.register_ecosystem

try:
    if EXPANSION_MANAGER is not None:
        _register_ecosystem = _load_ecosystem_register()
        ECOSYSTEM_MANAGER = _register_ecosystem(app, globals(), EXPANSION_MANAGER)
        app.logger.info("JARVIS ecosystem ready: %s", ECOSYSTEM_MANAGER.root)
except Exception as _ecosystem_error:
    app.logger.exception("JARVIS ecosystem could not start: %s", _ecosystem_error)

