# ==================== BDFD-ONLY PUBLIC TUNNEL RELAY ====================
# The tunnel should point to 127.0.0.1:8766, NOT the full JARVIS web server
# on 8765. This second Flask app forwards only the authenticated BDFD API
# routes. It deliberately does not publish the dashboard, settings, gateway,
# self-upgrade UI, or any other JARVIS endpoints.

_BDFD_MAIN_PORT = int(os.environ.get("JARVIS_PORT", "8765"))
_BDFD_RELAY_PORT = int(os.environ.get("JARVIS_BDFD_RELAY_PORT", "8766"))
_BDFD_RELAY_ALLOWED = {
    ("GET",  "/api/bdfd/health"),
    ("POST", "/api/bdfd/chat"),
    ("POST", "/api/bdfd/messages"),
    ("POST", "/api/bdfd/outbox"),
    ("GET",  "/api/bdfd/outbox/next"),
    ("POST", "/api/bdfd/outbox/ack"),
    ("GET",  "/api/bdfd/conversation"),
}
_bdfd_relay_app = Flask("jarvis_bdfd_only_public_relay")

@_bdfd_relay_app.route("/", defaults={"unused_path": ""}, methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"])
@_bdfd_relay_app.route("/<path:unused_path>", methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"])
def _bdfd_relay_forward(unused_path=""):
    path = request.path
    method = request.method.upper()
    if (method, path) not in _BDFD_RELAY_ALLOWED:
        return jsonify({"ok": False, "error": "This relay exposes only the authenticated BDFD bridge endpoints."}), 404
    if request.content_length is not None and request.content_length > 32768:
        return jsonify({"ok": False, "error": "Request body is too large."}), 413

    # Forward only the headers the bridge needs; never forward hop-by-hop or
    # client-supplied proxy headers.
    forward_headers = {}
    for header_name in ("Authorization", "Content-Type", "Accept", "X-JARVIS-Bridge-Key"):
        header_value = request.headers.get(header_name)
        if header_value:
            forward_headers[header_name] = header_value

    upstream_url = "http://127.0.0.1:%d%s" % (_BDFD_MAIN_PORT, path)
    try:
        upstream = requests.request(
            method=method,
            url=upstream_url,
            params=request.args,
            data=request.get_data(cache=True) if method != "GET" else None,
            headers=forward_headers,
            timeout=(5, 120),
            allow_redirects=False,
        )
        response = Response(
            upstream.content,
            status=upstream.status_code,
            content_type=upstream.headers.get("Content-Type", "application/json"),
        )
        response.headers["Cache-Control"] = "no-store"
        return response
    except requests.RequestException:
        app.logger.warning("BDFD public relay could not reach the local JARVIS API")
        return jsonify({"ok": False, "error": "The local JARVIS bridge is unavailable."}), 502


def _run_bdfd_public_relay():
    # Loopback-only. The SSH tunnel client on this same Android device can
    # reach it, while it is not directly listening on the phone's Wi-Fi IP.
    _bdfd_relay_app.run(
        host="127.0.0.1",
        port=_BDFD_RELAY_PORT,
        debug=False,
        threaded=True,
        use_reloader=False,
    )

